export const FROZEN_RANKFORGE_CANDIDATES = [{"runId":"01931bbd-72d9-4d00-8a07-c847587f80bd","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A friendly, credible B2B agency system for RankForge Kenya: a dark violet photographic hero framing the page top, a long light-neutral body of badge-headed sections with alternating faint lavender surfaces, violet pill CTAs as the only saturated recurring accent, a deliberately tall asymmetric services card collection as the commercial core, narrative splits with floating metric chips, a photo-backed testimonial band, and dark conversion surfaces (newsletter band, near-black contact banner, dense footer) closing the page. Three-family typography (geometric display, structured H2, humanist body) with capitalize heading voice.","signatureTraits":[{"id":"dark-violet-photo-hero","description":"Full-bleed ~1.07-viewport hero with a collaborative-workplace photograph under a dark violet wash, carrying the largest display headline on the page and one violet pill CTA.","sourceTraitId":"dark-violet-photo-hero"},{"id":"floating-pill-nav-cta","description":"Header with a centered inline navigation strip (Poppins-style 15px/600 capitalize links) and a distinct violet pill action CTA at the header's right; header compresses and collapses to a compact mobile menu with the CTA still reachable.","sourceTraitId":"floating-pill-nav-cta"},{"id":"about-split-portrait","description":"Near-full-height light editorial split: large portrait-orientation photo displayed within a soft lavender circular/blob mask on one side, dense multi-bullet copy on the other.","sourceTraitId":"about-split-portrait"},{"id":"very-tall-card-collection","description":"The tallest homepage region (~1.86 viewports) holds an asymmetric services collection: a 4-across icon-card row, then a 2-across wide-card row, then another 4-across row — equal white rounded cards with icon chips and per-card violet pill actions.","sourceTraitId":"very-tall-card-collection"},{"id":"narrative-split-with-stat-chips","description":"Two sequential narrative splits pairing medium imagery with copy and small floating metric-style chips, one image right-aligned, one left-aligned; chips are the focal parallax/reveal elements.","sourceTraitId":"narrative-split-with-stat-chips"},{"id":"accordion-faq-and-testimonials","description":"A light FAQ band with flat illustration montage left and violet pill-shaped accordion rows right (first item expanded in dark text, rest as saturated violet pills with trailing chevrons), followed by a photo-backed testimonial band: full-bleed office photograph with white rounded review cards and a dark accent quote card over the left half.","sourceTraitId":"accordion-faq-light-band"},{"id":"compact-newsletter-dark-contact-footer","description":"A compact (~0.38 viewport) newsletter band with inline name/email fields, then a dark contact/footer region opening with a near-black full-width contact banner and dense multi-column dark footer.","sourceTraitId":"compact-newsletter-dark-contact-footer"},{"id":"violet-pill-button-system","description":"Systemic rounded-pill violet buttons with small trailing arrow/plus glyphs used for every CTA and per-card action, plus small uppercase pill badges preceding section headings; violet is low-to-mid frequency accent on neutral surfaces; a light trusted-logos strip with reduced-weight marks appears early in the body.","sourceTraitId":"violet-pill-button-system"}],"fidelityPriorities":["Page silhouette: dark hero → light body sequence → photo mass → dark conversion close; the light/dark surface sequencing is the strongest identity signal","First viewport: full-bleed dark violet photo hero with 60px-class display headline and violet pill CTA","Region topology and proportions: 12-section rhythm including the unusually tall ~1.86-viewport services collection","Violet pill button/badge system as the sole saturated recurring accent","Three-family typography relationships and capitalize heading voice","Photography grammar: workplace-context imagery with dark overlays and masked portrait","Responsive reflow: single-column stacking without content removal","Motion: scroll-reveal based, no structural movement (parallax replaced per Adaptation Contract)"],"tokens":{"color_bg_body":"#F9FAFB","color_bg_light":"#F0F0F0","color_bg_lavender_tint":"#F0E0FF","color_surface_card":"#FFFFFF","color_surface_dark":"#101010","color_surface_footer_dark":"#505050","color_hero_wash":"#301F40","color_hero_wash_deep":"#604070","color_text_body":"#374151","color_text_on_dark":"#FFFFFF","color_accent_violet":"#8E2DE2","color_accent_violet_deep":"#4E2FDA","color_accent_violet_hover":"#7A24C9","radius_pill":"999px","radius_card":"12px","radius_chip":"10px","container_max":"1200px","container_narrow":"760px","gutter_desktop":"40px","gutter_tablet":"24px","gutter_mobile":"20px","space_xs":"8px","space_sm":"16px","space_md":"24px","space_lg":"48px","space_xl":"80px","space_2xl":"clamp(96px, 10vw, 140px)","motion_fast":"150ms","motion_standard":"300ms","motion_reveal":"500ms","ease_primary":"cubic-bezier(0.4, 0, 0.2, 1)"},"globalGrid":{"containerLogic":"Full-bleed section surfaces with a centered ~1200px content container; gutters 40px desktop / 24px tablet / 20px mobile. The hero and testimonial bands use full-bleed photographic backgrounds with content inside the same container. The services collection uses the standard container but spans ~1.86 viewports vertically across three card rows (4-up, 2-up wide, 4-up). Splits use roughly 45/55 two-column arrangements; the tall collection and splits stack to single column under ~900px.","columnRatios":["1:1 (narrative splits, about split)","45:55 (about split portrait/copy variant)","4-across equal cards (services rows 1 and 3)","2-across wide cards (services row 2)","5-across reduced-weight logo strip","3–4 column dark footer"]},"spacingRhythm":"Editorial SaaS rhythm: generous section padding (~clamp(80px, 9vw, 140px) top/bottom for major sections), tight internal gaps within card rows (24–32px), compact nav strip (header ~143px desktop incl. nav strip, compressing on mobile). The services collection is intentionally taller than other sections and must not be compressed to normalize rhythm; FAQ and testimonial regions stay at standard scale; newsletter band is deliberately compact (~0.38 viewport).","typographyRoles":[{"role":"display_xl / h1","description":"Figtree 60px/700, 78px line-height, capitalize — hero headline only; scales to ~40px mobile. Fallback: closest rounded-geometric sans if Figtree unavailable."},{"role":"h2","description":"Montserrat 40px/700, 48px line-height, 0.8px letter-spacing, capitalize — all section headings, typically preceded by a small violet pill badge label."},{"role":"feature_heading","description":"Figtree 40px/700, 0.8px tracking, capitalize — sub-headings inside splits and card titles, creating a compressed level below H2."},{"role":"body","description":"Poppins 16px/400, 22.4px line-height — all paragraph copy; measure ~60–75ch maximum."},{"role":"nav_button_badge","description":"Poppins 15px/600, capitalize — navigation links, pill CTA labels, badges and card action buttons."},{"role":"small_metadata","description":"Poppins 13–14px/400 — footer legal lines, form helper text, chip captions."}],"colorRoles":[{"role":"dominant_surface","description":"Light neutral #F9FAFB–#F0F0F0 with occasional faint lavender tints (#F0E0FF) — the majority of the page (~60–65% of visual mass)."},{"role":"dark_anchor","description":"Near-black #101010 and dark gray #505050 family frame the page: dark violet hero wash top, near-black contact banner, dark footer bottom (~20–25% of mass)."},{"role":"primary_accent","description":"Saturated violet #8E2DE2 (deep variant #4E2FDA) — CTA fills, pill badges, FAQ pills, icon chips; low-to-mid frequency, concentrated on actionable elements."},{"role":"text","description":"Body text #374151 on light surfaces; white on dark surfaces and hero overlay."},{"role":"card_surface","description":"White rounded cards over light and photographic surfaces."}],"surfaceLanguage":"Flat, friendly SaaS surfaces: no glassmorphism, no heavy gradients, no textured backgrounds. Depth comes from (1) surface shifts between light gray, lavender-tinted, photographic and dark bands; (2) soft subtle shadows on white cards and floating metric chips; (3) the soft lavender circular/blob mask on the about portrait; (4) dark purple overlay wash on photographic hero and darkening overlay on the testimonial backdrop. Radii are pill (999px) for buttons/badges/FAQ rows and ~12px for cards; borders are minimal or absent.","headerNavigation":"Desktop header ~143px total: top bar with logo left; below it a centered inline navigation strip (~568px, 15px/600 capitalize links) with a violet pill CTA at the header's right ('Request an SEO Consultation'). Header sits over the dark hero as a transparent/light-on-dark bar; becomes solid light on scrolled state. Mobile: header compresses, nav collapses to a compact menu, pill CTA remains reachable in or beside the menu bar.","homepageFirstViewport":{"summary":"First viewport = header (transparent over hero, with centered nav strip and violet pill CTA) + full-bleed dark violet photographic hero (~1.07 viewport heights): collaborative-workplace photo under a dark purple wash (target dominant tone near #301F40–#604070, luminance ~40–66), headline 'Get found when your customers are already searching.' in 60px Figtree-class display with supporting copy, primary pill CTA 'Request an SEO Consultation' and secondary CTA 'Explore Our Services'. Text mass left-weighted; photo texture visible through the wash; the top of the next light section may peek at very tall viewports.","regionIds":["region_hero"]},"homepageRegions":[{"id":"region_hero","purpose":"Header + full-bleed dark violet photo hero: display headline 'Get found when your customers are already searching.', supporting copy on technical SEO / content strategy / focused execution, primary pill CTA 'Request an SEO Consultation', secondary CTA 'Explore Our Services'.","imageRoleId":"img_hero_dark_office","sourceEvidenceRegionIds":["region-0","region-1","region-2"]},{"id":"region_about_split","purpose":"Near-full-height light editorial split: masked portrait photo in soft lavender blob mask introducing RankForge's approach ('SEO without the noise' spirit), with dense multi-bullet copy on expertise and philosophy; optional small stat-style chips acceptable within the split language.","imageRoleId":"img_about_portrait_masked","sourceEvidenceRegionIds":["region-3"]},{"id":"region_trust_strip","purpose":"Light trust strip with centered Montserrat heading and a horizontal row of reduced-weight partner/credential marks. Content constraint: no invented client logos — use generic text-based marks only if the business supplies them; otherwise present the strip as a capability/credential line at reduced visual weight.","sourceEvidenceRegionIds":["region-4"]},{"id":"region_services_collection","purpose":"Commercial core: very tall (~1.86 viewport) services collection presenting exactly the six RankForge services across an asymmetric card layout — 4-across icon-card row, 2-across wide-card row, 4-across row (cards for SEO Strategy, Technical SEO, Local SEO, SEO Content Strategy, Ecommerce SEO, SEO Audits plus supporting capability cards); white rounded cards, icon chips, per-card violet pill actions.","imageRoleId":"img_service_icon_chips","sourceEvidenceRegionIds":["region-5"]},{"id":"region_narrative_split_one","purpose":"Narrative split (image right, copy left) with floating metric-style chips: describe the problem-to-clarity story — sites not ranking for commercially important searches, strategy-first diagnosis. Chips may express process/positioning labels, never invented statistics.","imageRoleId":"img_narrative_person_one","sourceEvidenceRegionIds":["region-6"]},{"id":"region_narrative_split_two","purpose":"Second narrative split (image left, copy right) with floating chips: the four-stage process (01 Diagnose, 02 Prioritise, 03 Execute, 04 Improve) presented alongside medium imagery with lavender-tinted background accents.","imageRoleId":"img_narrative_person_two","sourceEvidenceRegionIds":["region-7"]},{"id":"region_faq","purpose":"Light FAQ band: flat illustration montage left, violet pill accordion stack right; first item expanded in dark text, remaining items as saturated violet pills with trailing chevrons. Content: honest SEO FAQs (scope, process, timelines framed without guarantees).","sourceEvidenceRegionIds":["region-8"]},{"id":"region_testimonials","purpose":"Photo-backed band: full-bleed office photograph darkened, white rounded cards and a dark accent quote card over the left half carrying the closing value proposition 'Ready to make organic search work harder for your business?' with pill CTA 'Talk to RankForge'. No invented testimonials — cards carry the value proposition and positioning statements.","imageRoleId":"img_testimonial_backdrop","sourceEvidenceRegionIds":["region-9"]},{"id":"region_newsletter","purpose":"Compact newsletter/lead-capture band with inline name and email fields and a violet pill submit action, feeding the central WAZIBIZ Form Service.","sourceEvidenceRegionIds":["region-10"]},{"id":"region_contact_footer","purpose":"Dark conversion close: near-black full-width contact banner ('Let's talk about where search can take your business.' with consultation CTA linking toward the contact route), then a dense dark multi-column footer with navigation, contact email hello@rankforgekenya.example, Nairobi/Kenya location line and legal row.","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Environmental business-context proof, not product display: candid collaborative workplace scenes for the darkened hero and testimonial backdrop; one portrait-orientation medium shot of a single person at a device inside a soft lavender blob mask for the about split; medium lightly-posed single-person shots with laptops/tablets for narrative splits; flat colorful illustration montage figures beside the FAQ and small square icon chips on service cards. Warm-neutral to slightly warm, moderate contrast, clean office backgrounds, restrained complexity, text-safe negative space where copy overlays imagery. Avoid: macro product shots, dramatic cinematic lighting, desaturated editorial fashion treatment, sterile studio backgrounds.","imageRoles":[{"id":"img_hero_dark_office","purpose":"Full-bleed collaborative-office photograph for the hero, wide landscape, people working at laptops, cropped to support a dark violet overlay wash and left-weighted text mass.","priority":"CRITICAL"},{"id":"img_about_portrait_masked","purpose":"Portrait-orientation medium shot of one practitioner at a device, displayed inside a soft lavender circular/blob mask in the about split.","priority":"CRITICAL"},{"id":"img_service_icon_chips","purpose":"Small square flat icon/illustration chips for service cards (REPEATABLE, one per card) — flat colorful vector-style marks, not photography.","priority":"HIGH"},{"id":"img_narrative_person_one","purpose":"Medium shot, lightly posed single person with laptop, clean light background, image right; hosts floating chip overlays.","priority":"HIGH"},{"id":"img_narrative_person_two","purpose":"Medium shot with tablet/device against clean or lavender-tinted background, image left; hosts floating chip overlays.","priority":"HIGH"},{"id":"img_testimonial_backdrop","purpose":"Full-bleed real-office photograph as the testimonial/value-prop band backdrop, darkened so overlaid cards remain readable.","priority":"CRITICAL"},{"id":"img_faq_illustration","purpose":"Flat illustration montage figures beside the FAQ stack (square, flat colorful style, NOT photographic).","priority":"NORMAL"}]},"motionGrammar":["Scroll-triggered reveal transitions on sections, cards and split imagery (substituting the reference's heavy parallax per Adaptation Contract 'mass'-level fidelity retained statically)","Floating metric-style chips in narrative splits receive slightly staggered reveal timing as the focal motion moment","Hero and testimonial backgrounds: subtle static depth cue (slight scale-in on reveal), no scroll-linked parallax","Violet pill buttons: 150ms background/shadow color transition on hover, visible focus ring, pressed state","FAQ accordion: 300ms expand/collapse with chevron rotation; first item open by default","Header: solid background transition on scroll; mobile menu slide/fade 200–300ms","All reveals respect prefers-reduced-motion: content appears without translation or scale","No structural scroll motion: no horizontal scroll, no section reordering; stable topology"],"responsiveContract":["Breakpoints: ~1440 desktop reference, ~1024 intermediate, ~768 tablet, 375 mobile","All 12 homepage sections persist on mobile — single-column stacking, never content removal","Services collection rows (4-up, 2-up, 4-up) collapse to stacked single-column cards, each retaining icon chip and pill action","Split regions stack image above copy (about portrait scales within its lavender mask)","Centered nav strip collapses to compact mobile menu; pill CTA stays reachable; header compresses from ~143px","Full-bleed photo regions crop imagery (object-position toward subject/text-safe area) while preserving overlay composition","Logo/trust strip reduces from 5-up row to wrapped smaller set","No horizontal overflow at any breakpoint; form fields and accordions full-width on mobile"],"innerPageVocabulary":["NARROW_NARRATIVE — centered narrow column for about-page philosophy text under an H2 badge heading","EDITORIAL_SPLIT — masked portrait or environmental image one side, dense bullets/principles other side (About principles: Commercial relevance, Technical clarity, Useful content, Continuous improvement)","STAGGERED_MEDIA — services detail pages alternating image/copy blocks per service","CARD_COLLECTION — reuse of the services card row pattern for service listing pages","PROCESS_SEQUENCE — four-step numbered sequence (Diagnose / Prioritise / Execute / Improve) with pill step markers","CONTACT_SPLIT — dark contact banner + form fields (Name, Company, Email, Phone, Website, help-topic select, Message) beside contact details"],"antiFallbackRules":["Do not compress the ~1.86-viewport services collection into a single uniform 3-up card grid — preserve the 4/2/4 asymmetric row structure","Do not replace the dark violet photographic hero with a flat color or gradient-only hero","Do not swap pill buttons for square/rectangular buttons — the pill system with trailing glyphs is identity-defining","Do not center every heading — H2s are badge-preceded and predominantly left-aligned except the trust-strip heading","Do not replace the lavender blob mask on the about portrait with a plain rectangle","Do not use generic fade-up on every section uniformly — stagger cards and chips","Do not lighten the dark contact banner / footer close — the near-black conversion close is part of the silhouette","Do not add glassmorphism, mesh gradients or neon effects absent from the reference","Do not invent testimonials, metrics, client logos, rankings or results — constrained content replaces reference proof elements"],"accessibilityAdaptations":["All violet-on-white pill text meets contrast (white text on #8E2DE2/#4E2DSA fills; dark text alternative if contrast fails)","Dark hero overlay ensures headline/CTA contrast ≥ 4.5:1 against the photographic wash","Visible focus rings on all pills, nav links, accordion triggers and form fields","Accordion uses semantic button + aria-expanded; form fields have persistent labels","prefers-reduced-motion disables reveals, staggering and scale effects","Mobile body type ≥ 16px; tap targets ≥ 44px including pill buttons and accordion rows","Decorative photos and illustration montages are aria-hidden; alt text only for meaningful imagery"],"declaredLimitations":["Heavy parallax choreography replaced with static-preserving scroll reveals per accepted Adaptation Contract (heavy_parallax unsupported)","Exact reference fonts assumed Figtree/Montserrat/Poppins; closest legal equivalents used if licensing/unavailability blocks exact families","Motion timing values unmeasured in reference — durations are best-practice estimates (150/300/500ms)","Trusted-logos strip cannot contain real client logos per business facts; presented as reduced-weight capability/credential line unless the client supplies marks","Floating metric chips render as label/status chips only — no quantitative claims permitted","Reference content, branding and photography are design evidence only and are never copied"]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":1,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5351,"completion_tokens_details":{"reasoning_tokens":137},"prompt_tokens":16130,"prompt_tokens_details":{"cached_tokens":0},"total_tokens":21481}},"createdAt":"2026-09-06T19:08:47.179Z"}},{"runId":"1936c17b-1b32-49ef-8a97-cb754630cf3f","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A friendly SaaS-style long-scroll B2B agency system for RankForge Kenya: dark violet photographic hero framing a light neutral body of badge-titled sections, an unusually tall asymmetric services card collection as the commercial core, narrative splits with floating metric-style chips, violet pill accordion FAQ, a photo-backed proof band, and dark conversion anchors (newsletter band + black contact banner into a dense dark footer). Violet is a low-to-mid frequency action accent, never a flood; surface shifts (dark hero → light gray bands with faint lavender tints → photographic mass → near-black bands) do the sequencing work.","signatureTraits":[{"id":"dark-violet-photo-hero-rankforge","description":"Full-bleed ~1.07-viewport hero (region-2) with a darkened collaborative-workspace photograph under a deep violet wash (dominant rgb(48,32,64) family), carrying the 60px Figtree display headline 'Get found when your customers are already searching.' and violet pill CTA 'Request an SEO Consultation'. CRITICAL: overlay must keep overlaid text at WCAG contrast; photographic background is darkened, never bright.","sourceTraitId":"dark-violet-photo-hero"},{"id":"floating-pill-nav-cta-rankforge","description":"Header bar (~143px desktop) with a centered inline navigation strip of Poppins 15px/600 capitalize links and a distinct violet pill CTA at the header's right ('Request an SEO Consultation'); collapses to a compact mobile menu while keeping the pill CTA reachable.","sourceTraitId":"floating-pill-nav-cta"},{"id":"about-split-portrait-rankforge","description":"Near-full-height (~0.97 viewport) light editorial split: large portrait-orientation photo of a practitioner at work inside a soft lavender circular/blob mask on the left, dense benefit/bullet copy on the right, Montserrat H2 with a small violet pill badge label.","sourceTraitId":"about-split-portrait"},{"id":"very-tall-card-collection-rankforge","description":"The tallest region (~1.86 viewports) holds the six RankForge services as an asymmetric card collection: rows of 4-across icon cards, then 2-across wide cards, then another 4-across; equal white rounded cards with icon chips and small violet pill per-card actions. Row rhythm (4/2/4) must be preserved to avoid monotony across the long scroll.","sourceTraitId":"very-tall-card-collection"},{"id":"narrative-split-stat-chips-rankforge","description":"Two sequential narrative split regions (~0.78 and ~0.97 viewports): one right-aligned image, one left-aligned montage, each pairing medium shots of a person at a device with copy and small floating chip cards. For RankForge, chips carry non-quantitative labels (e.g. process stage markers '01 Diagnose'–'04 Improve', service-focus tags) — no fabricated statistics.","sourceTraitId":"narrative-split-with-stat-chips"},{"id":"accordion-faq-light-band-rankforge","description":"Light ~0.8-viewport FAQ region with a left flat illustration montage (~90px displayed figures) and right-stacked accordion rows styled as saturated violet pills with trailing chevrons, first item expanded in dark text.","sourceTraitId":"accordion-faq-light-band"},{"id":"photo-backed-proof-band-rankforge","description":"A ~0.48-viewport band whose background is a full-bleed real-office photograph (1440x630 mass, density ~0.79) with overlaid white rounded cards plus a dark accent card on the left half. For RankForge this becomes a 'why RankForge / positioning' proof band (principles, commercial-growth positioning) — photographic mass and overlay card composition preserved, but no invented testimonials or metrics.","sourceTraitId":"photo-backed-testimonials"},{"id":"violet-pill-button-system-rankforge","description":"Systemic rounded-pill violet buttons with small trailing arrow/plus glyphs used for every CTA and per-card action (accent violets rgb(142,45,226) / rgb(78,47,218) role anchors), plus small uppercase-style pill badges preceding each Montserrat H2.","sourceTraitId":"violet-pill-button-system"}],"fidelityPriorities":["1. Page silhouette and surface sequence — dark hero, light gray body bands with faint lavender tints, photographic mid-page mass, near-black band, dark footer; this alternation is the strongest identity carrier.","2. First viewport — dark violet photo hero with 60px display headline and violet pill CTA at ~1.07 viewport height.","3. Violet pill button/badge system — CTA geometry, per-card pills and badge labels appear everywhere; losing them dissolves the template voice.","4. Region topology and proportions — 12-section ordering including the ~1.86-viewport services collection and the two narrative splits.","5. Typography relationships — three-family stack (Figtree display, Montserrat H2, Poppins body/UI) with capitalize heading transforms and the compressed 40px sub-heading role.","6. Photographic grammar — darkened workplace backdrops, blob-masked portrait, medium person-at-device shots, flat illustration chips.","7. Component geometry — white rounded cards, icon chips, violet pill accordions, floating chip cards.","8. Responsive identity — all 12 sections retained on mobile via single-column stacking, photo-backed overlays preserved by cropping."],"tokens":{"color_brand_primary":"#8E2DE2","color_brand_secondary":"#4E2FDA","color_hero_wash":"#302040","color_hero_wash_light":"#604070","color_surface_body":"#F9FAFB","color_surface_light":"#F0F0F0","color_surface_lavender_tint":"#F0E0FF","color_surface_dark":"#101010","color_surface_footer":"#505050","color_text_body":"#374151","color_text_on_dark":"#F9FAFB","radius_pill":"999px","radius_card":"12px","container_max":"1440px","container_content":"1200px","space_section_normal":"clamp(64px, 8vw, 96px)","space_section_generous":"clamp(96px, 12vw, 144px)","font_display":"Figtree, sans-serif (700)","font_heading":"Montserrat, sans-serif (700, 0.8px tracking)","font_body":"Poppins, sans-serif","motion_standard":"300ms ease-out","motion_reveal":"500ms cubic-bezier(0.22, 0.61, 0.36, 1)"},"globalGrid":{"containerLogic":"Full-bleed dark/photo surfaces (hero, photo-backed band, black contact banner, footer) span 100% viewport width; inner content constrained to a ~1200px centered container with ~40px desktop / ~24px mobile gutters. Card grids use a 4-column base collapsing to 2 then 1; splits use asymmetric 5/7 or 7/5 two-column layouts stacking image-over-copy on mobile.","columnRatios":["4-up equal card grid (desktop) / 2-up (tablet) / 1-up (mobile)","2-up wide card row","5:7 asymmetric split (image:copy)","7:5 mirrored split (copy:image)","5:7 FAQ illustration:accordion split","centered single column (nav strip, newsletter, logo strip)"]},"spacingRhythm":"Sections breathe generously: light body bands use ~96-144px vertical padding; the tall services collection uses consistent ~64px internal row gaps with a repeated card-row rhythm (4/2/4); the compact newsletter band is deliberately tighter (~64-80px) as a fast conversion beat before the dense dark footer. Preserve the reference's irregular editorial rhythm — do not normalize all sections to one padding value.","typographyRoles":[{"role":"display_xl / H1","description":"Figtree 700, 60px/78px desktop, capitalize, white on dark hero — 'Get found when your customers are already searching.' Scale to ~40px tablet, ~32px mobile."},{"role":"h2_section","description":"Montserrat 700, 40px/48px, 0.8px letter-spacing, capitalize, typically preceded by a small violet pill badge label."},{"role":"h3_feature","description":"Compressed sub-heading role: Figtree 700, 40px/40px, 0.8px tracking — used for card titles and sub-block headings inside splits; drop to ~24-28px on mobile."},{"role":"body","description":"Poppins 400, 16px/22.4px, neutral gray rgb(55,65,81); max measure ~65-75ch in splits."},{"role":"ui_link_button","description":"Poppins 600, 15px, capitalize — navigation links, pill CTA labels and badges."},{"role":"chip_metadata","description":"Small Poppins labels for floating chips and badges; 12-14px, 600, capitalize."}],"colorRoles":[{"role":"primary_action_accent","description":"Saturated violet (rgb(142,45,226) anchor) reserved for pill CTAs, badges, FAQ pills and icon chips — low-to-mid page frequency; never flood surfaces with it."},{"role":"secondary_accent","description":"Deeper violet (rgb(78,47,218)) for hover/darker states and secondary accents."},{"role":"dominant_surface","description":"Light neutral rgb(240,240,240)-family / body rgb(249,250,251) covers the majority of the page."},{"role":"tint_surface","description":"Faint lavender rgb(240,224,255) used sparingly as band tints and the portrait blob mask."},{"role":"dark_anchor","description":"Near-black rgb(16,16,16) for the contact banner; rgb(48,32,64) violet-dark for the hero wash; dark footer bands (~rgb(80,80,80)/rgb(64,48,48))."},{"role":"text_roles","description":"Body text rgb(55,65,81); white/near-white text on dark and photo surfaces."}],"surfaceLanguage":"Flat, friendly SaaS surfaces: no gradients beyond the hero's dark violet photo overlay, no glassmorphism, minimal shadows (soft card elevation only). Cards are white, rounded (~12px), on light gray bands. Rounded-pill geometry is systemic for buttons, badges and accordion rows. One organic soft lavender blob mask for the about portrait. Dark regions are flat solid fills.","headerNavigation":"Desktop header ~143px: logo left, centered inline nav strip of Poppins 15px/600 capitalize links, violet pill CTA fixed at right. Static-to-scrolled behavior: keep surface light/transparent over hero then solid on scroll. Mobile: compress header height, collapse nav into a compact menu while the pill CTA remains visible/reachable. All 14 nav items retained across breakpoints (no content removal).","homepageFirstViewport":{"summary":"Header (~0.16 viewport) plus nav strip merge with the full-bleed dark violet photographic hero (region-2, ~1.07 viewports): darkened collaborative-workspace background, deep violet overlay wash, left-anchored 60px Figtree headline 'Get found when your customers are already searching.', supporting copy on technical SEO / content strategy / focused execution, primary violet pill CTA 'Request an SEO Consultation' and secondary 'Explore Our Services'. Overlaid text must retain WCAG contrast against the darkened photo. Mobile: same overlay composition, cropped image, stacked headline/CTAs.","regionIds":["homepage_hero"]},"homepageRegions":[{"id":"homepage_hero","purpose":"Header + centered inline nav + dark violet photo hero with display headline, supporting organic-visibility copy, primary 'Request an SEO Consultation' and secondary 'Explore Our Services' pill CTAs.","imageRoleId":"hero_darkened_office","sourceEvidenceRegionIds":["region-0","region-1","region-2"]},{"id":"homepage_about_split","purpose":"Light near-full-height editorial split introducing RankForge's approach: blob-masked portrait of a practitioner at work left, Montserrat H2 with violet badge and dense benefit bullets right ('SEO built around commercial growth, not vanity metrics').","imageRoleId":"about_masked_portrait","sourceEvidenceRegionIds":["region-3"]},{"id":"homepage_trust_strip","purpose":"Light strip with centered Montserrat heading and a horizontal row of five reduced-weight credibility markers. Adapted: no invented client logos — use desaturated generic capability/sector keyword marks (e.g. 'Local SEO', 'Ecommerce SEO') at reduced visual weight.","sourceEvidenceRegionIds":["region-4"]},{"id":"homepage_services_collection","purpose":"The commercial core: very tall asymmetric white-card collection presenting the six RankForge services (SEO Strategy, Technical SEO, Local SEO, SEO Content Strategy, Ecommerce SEO, SEO Audits) in 4-up icon-card / 2-up wide-card / 4-up rows with violet pill per-card actions.","imageRoleId":"service_icon_chips","sourceEvidenceRegionIds":["region-5"]},{"id":"homepage_narrative_problems","purpose":"Narrative split, image right: customer-problem copy (little qualified traffic, competitors above them on Google, unclear SEO strategy) paired with a person-at-device photo and floating chip cards carrying non-quantitative labels.","imageRoleId":"narrative_person_device","sourceEvidenceRegionIds":["region-6"]},{"id":"homepage_process","purpose":"Mirrored narrative split, montage left: the four-stage process (01 Diagnose, 02 Prioritise, 03 Execute, 04 Improve) with floating stage-marker chips over imagery.","imageRoleId":"narrative_person_device","sourceEvidenceRegionIds":["region-7"]},{"id":"homepage_faq","purpose":"Light FAQ band: flat illustration montage left, violet pill accordion right answering common SEO questions (first item expanded).","imageRoleId":"faq_illustration_montage","sourceEvidenceRegionIds":["region-8"]},{"id":"homepage_proof_band","purpose":"Full-bleed office-photo band with overlaid white cards and a dark accent card on the left: RankForge positioning/principles (Commercial relevance, Technical clarity, Useful content, Continuous improvement) — no invented testimonials.","imageRoleId":"proof_band_office_backdrop","sourceEvidenceRegionIds":["region-9"]},{"id":"homepage_newsletter","purpose":"Compact conversion band with inline name/email fields wired to the WAZIBIZ Form Service; single tight beat before the footer.","sourceEvidenceRegionIds":["region-10"]},{"id":"homepage_contact_footer","purpose":"Black full-width contact banner ('Ready to make organic search work harder for your business?' + 'Talk to RankForge') transitioning into a dense dark multi-column footer with navigation, services list, contact email and closing conversion beat.","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Documentary-commercial photography of real work environments, not studio stock. People are shown candidly working at laptops/devices in clean office settings, usually one to two per frame, gaze toward task or occasionally camera. Warm-neutral to slightly warm grading, moderate contrast, restrained backgrounds with text-safe negative space where copy overlays imagery. Hero and proof-band backdrops are darkened under violet/neutral washes. Flat colorful illustration montages (not photography) accompany the FAQ. No macro product shots, no dramatic cinematic lighting, no desaturated editorial treatment, no hyper-saturated grading.","imageRoles":[{"id":"hero_darkened_office","purpose":"Full-bleed darkened collaborative-workspace photo as hero backdrop supporting overlaid display headline and pill CTAs under a deep violet wash; wide landscape, subject mass right-of-copy leaving text-safe left space.","priority":"CRITICAL"},{"id":"about_masked_portrait","purpose":"Portrait-orientation (~2:3) medium shot of a single practitioner at a device inside a soft lavender blob/circle mask on a light surface.","priority":"CRITICAL"},{"id":"service_icon_chips","purpose":"Small square icon/illustration chips (~56-90px displayed) topping the six service cards; flat, colorful, consistent set.","priority":"HIGH"},{"id":"narrative_person_device","purpose":"Medium shots of a single person working at a laptop/tablet against clean light or lavender backgrounds, with floating chip cards; used in both narrative splits (one right-aligned, one left-aligned montage).","priority":"HIGH"},{"id":"faq_illustration_montage","purpose":"Flat illustration montage figures beside the FAQ accordion, square sources ~1:1, ~90px displayed elements composed as a small cluster.","priority":"NORMAL"},{"id":"proof_band_office_backdrop","purpose":"Full-bleed real-office photograph (landscape ~1440x630) as backdrop for overlaid white cards and a dark accent card, darkened for overlay readability.","priority":"CRITICAL"}]},"motionGrammar":["Scroll-triggered reveal transitions for sections and card rows (substituting the reference's heavy parallax per the Adaptation Contract): fade + small upward travel, ~500ms, staggered ~80ms across card grids.","Floating chip cards in the narrative splits receive a subtle slower drift/offset relative to their parent imagery (reduced-motion-safe depth cue, no true parallax).","Violet pill buttons: background-color/darkening transition toward rgb(78,47,218) plus slight shadow lift on hover, ~300ms ease-out; visible focus ring for keyboard users.","FAQ accordion pills: smooth expand/collapse height transition ~300ms; chevron rotation; expanded row switches to light surface with dark text.","No structural motion: section topology stays stable under scroll; no horizontal scroll, no section reordering, no generic fade-up on every element."],"responsiveContract":["Breakpoints: desktop ≥1200px, tablet ~768-1199px, mobile <768px; mobile capture at 375px retains all sections and nav items — reflow, never removal.","Card grids: 4-across → 2-across (tablet) → single column (mobile), each card retaining its icon chip and pill action.","Split regions (about, narrative x2, FAQ) stack image above/below copy; the portrait scales down within its blob mask.","Header compresses; centered nav strip collapses into a compact mobile menu while the pill CTA stays reachable.","Full-bleed photo regions (hero, proof band) crop imagery while preserving overlay composition: stacked headline, overlaid cards retained.","Trust strip reduces from a 5-up row to a wrapped or scrollable smaller set.","No horizontal overflow at any breakpoint; no clipped critical content; type scales down per typographyRoles."],"innerPageVocabulary":["HERO_LIGHT_INNER — compact light inner-page hero with violet badge, Montserrat H2 and short intro; no dark banner on every inner page.","EDITORIAL_SPLIT — reusable 5:7 or 7:5 image/copy split extending the about-split language for About and service detail pages.","CARD_COLLECTION — the 4/2/4 (or simplified 3-up / 2-up) white-card grid with icon chips and pill actions for the six services.","PROCESS_SEQUENCE — numbered four-stage sequence (01 Diagnose … 04 Improve) using chip-card styling from the narrative splits.","ACCORDION_BAND — FAQ/violet-pill accordion section reusable on service and contact pages.","CONTACT_SPLIT — dark-accent contact area with WAZIBIZ Form Service form (Name, Company, Email, Phone, Website, help-topic select, Message) beside contact details.","QUIET_CTA — compact light conversion band with a single violet pill CTA.","NARROW_NARRATIVE — single narrow text column for principle/philosophy copy on About."],"antiFallbackRules":["Do not replace the 4/2/4 asymmetric services collection with a uniform 3-column card grid.","Do not remove the dark violet photographic hero in favor of a plain light hero.","Do not flood the page with violet; accent frequency must stay low-to-mid on a dominant light neutral body.","Do not replace pill buttons/badges/accordions with square or ghost buttons.","Do not invent testimonials, client logos, metrics or percentage chips — stat-style chips carry process stages and capability labels only.","Do not add gradients, glassmorphism or heavy shadows absent from the reference.","Do not default all imagery to centered subjects or sterile studio backgrounds; keep environmental office contexts.","Do not apply generic fade-up to every section; use the staggered reveal + chip-drift grammar only.","Do not shrink the services collection into a short strip; its ~1.86-viewport scale is identity-defining."],"accessibilityAdaptations":["All overlaid hero/proof-band text passes WCAG AA contrast via darkened photo washes; verified against the actual chosen imagery.","Visible keyboard focus rings on all pill CTAs, nav links and accordion controls; accordion rows are real buttons with aria-expanded.","FAQ accordion content available without hover; no hover-only essential behavior.","prefers-reduced-motion disables reveal travel, chip drift and long transitions while preserving visibility and state feedback.","Mobile body type never below 16px equivalent; nav and CTAs meet touch-target sizes.","Form labels, help-topic select and error states fully accessible; submission runs through the WAZIBIZ Form Service with Turnstile."],"declaredLimitations":["Adaptation Contract: reference heavy parallax replaced by reveal transitions and reduced-motion-safe chip-drift depth cues; macro composition and rhythm preserved statically.","Reference stat chips show metrics ('Taxa de Crescimento 45.80%'); business facts forbid quantitative claims, so chips carry non-quantitative process-stage and capability labels while preserving chip geometry and placement.","Reference testimonial cards over office photo become a positioning/principles proof band over the same photographic mass — no invented testimonials.","Reference client logos strip becomes a desaturated capability/sector keyword strip — no fabricated customer marks.","Exact reference font files not supplied; Figtree/Montserrat/Poppins used via closest legal web-font sources with declared fallback stacks.","No measured motion timing values from the reference; timing uses standard 300-500ms ease-out conventions declared here rather than copied measurements."]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":2,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5635,"completion_tokens_details":{"reasoning_tokens":256},"prompt_tokens":16251,"prompt_tokens_details":{"cached_tokens":0},"total_tokens":21886}},"createdAt":"2026-09-06T17:35:08.577Z"}},{"runId":"1ae3fc13-9ca8-44a9-a1fa-c36a23f4b768","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A long-scroll agency system that alternates dark anchored masses with light neutral surfaces: a dark violet photographic hero with 60px-class display headline and violet pill CTA, then light gray/lavender-tinted editorial sections — masked-portrait about split, an unusually tall asymmetric services card collection with icon chips and per-card pill buttons, narrative splits with floating metric chips, violet pill accordion FAQ beside flat illustration montage, photo-backed testimonial cards, a compact newsletter band, and a black contact banner flowing into a dense dark footer. Three-family type stack (rounded-geometric display, clean H2, legible body) with capitalize transforms; saturated violet pills are the only high-frequency accent against near-neutral surfaces.","signatureTraits":[{"id":"dark-violet-photo-hero","description":"Full-bleed ~1.07-viewport hero with photographic collaborative-office background under a dark violet wash (target dominant rgb(48,32,64) family), carrying the RankForge display headline 'Get found when your customers are already searching.' plus primary pill CTA 'Request an SEO Consultation' and secondary 'Explore Our Services'.","sourceTraitId":"dark-violet-photo-hero"},{"id":"floating-pill-nav-cta","description":"Header bar (~143px desktop) with centered inline navigation strip and a distinct violet pill CTA at the header's right ('Request an SEO Consultation'); Poppins-class 15px/600 capitalize links collapsing to a compact mobile menu.","sourceTraitId":"floating-pill-nav-cta"},{"id":"about-split-portrait","description":"Near-full-height (~870px) light editorial split: large portrait-orientation photo inside a soft lavender blob/circle mask on the left, dense multi-bullet copy on the right presenting RankForge's approach ('SEO without the noise.' adapted to homepage context).","sourceTraitId":"about-split-portrait"},{"id":"very-tall-card-collection","description":"The tallest region (~1.86 viewports) holds the six RankForge services as an asymmetric card collection: 4-across icon-chip card row, 2-across wide-card row, then remaining cards; equal white rounded cards each with a small violet pill action and 56px icon chip.","sourceTraitId":"very-tall-card-collection"},{"id":"narrative-split-with-stat-chips","description":"Two sequential narrative split regions (~0.7 and ~0.97 viewports) pairing imagery with copy and small floating metric/label chips; one image right-aligned, one left-aligned. RankForge replaces invented metrics with non-quantitative chips (e.g. 'Diagnose — Prioritise — Execute — Improve' stage chips or problem statements), keeping the floating-chip visual role without fabricated numbers.","sourceTraitId":"narrative-split-with-stat-chips"},{"id":"accordion-faq-light-band","description":"Light ~0.8-viewport FAQ band: left flat-illustration montage, right-stacked pill accordion rows — first item expanded in dark text, remaining items as saturated violet pills with trailing chevrons. Populated with RankForge service/process questions only.","sourceTraitId":"accordion-faq-light-band"},{"id":"photo-backed-testimonials","description":"Full-bleed office-photograph backdrop (1440x630-class mass) with white rounded overlay cards and a dark accent quote card on the left. Because RankForge forbids invented testimonials, this region carries the photo-backed card composition with credible non-testimonial content: the closing positioning message and process/proof framing inside the same card geometry (see adaptation note), preserving the visual mass and card system.","sourceTraitId":"photo-backed-testimonials"},{"id":"compact-newsletter-dark-contact-footer","description":"Compact ~341px newsletter band with inline fields (ranked insight/updates subscription), followed by a ~721px dark contact/footer region beginning with a black full-width banner carrying 'Ready to make organic search work harder for your business?' and CTA 'Talk to RankForge', flowing into a dense dark multi-column footer with contact email hello@rankforgekenya.example and navigation.","sourceTraitId":"compact-newsletter-dark-contact-footer"}],"fidelityPriorities":["1. Page silhouette and dark/light surface sequence (dark hero, light body, lavender tints, photo mass, black banner, dark footer)","2. First viewport: dark violet photographic hero with display headline and violet pill CTA","3. Very tall asymmetric services card collection (region-5 scale and row rhythm)","4. Violet pill button/badge/accent system frequency and geometry","5. Three-family typography hierarchy with capitalize transforms","6. Image-mass bands: masked portrait, narrative split imagery, photo-backed testimonial backdrop","7. Floating chip language and card component geometry","8. Responsive stacking identity (single-column reflow, no content removal)"],"tokens":{"brand-primary":"#8E2DE2","brand-secondary":"#4E2FDA","brand-accent":"#8E2DE2","surface-page":"#F9FAFB","surface-light":"#F0F0F0","surface-lavender-tint":"#F0E0FF","surface-dark-banner":"#101010","surface-footer-dark":"#505050","surface-footer-deep":"#403030","hero-wash":"#302040","hero-wash-light":"#604070","text-primary":"#111827","text-body":"#374151","text-on-strong":"#FFFFFF","action-primary":"#8E2DE2","action-primary-hover":"#7B24C9","action-secondary-outline":"rgba(142,45,226,0.15)","border-default":"rgba(17,24,39,0.10)","border-subtle":"rgba(17,24,39,0.06)","focus-ring":"#4E2FDA","overlay-hero":"rgba(48,32,64,0.72)","overlay-photo":"rgba(16,16,16,0.55)","container-max":"1200px","container-narrow":"720px","gutter-mobile":"20px","gutter-desktop":"40px","radius-card":"16px","radius-pill":"999px","radius-icon-chip":"12px","shadow-card":"0 6px 24px rgba(17,24,39,0.08)","shadow-chip":"0 4px 14px rgba(17,24,39,0.12)","motion-standard":"250ms","ease-primary":"cubic-bezier(0.33,1,0.68,1)"},"globalGrid":{"containerLogic":"Full-bleed surfaces (hero, photo-backdrop, newsletter, black banner, footer) with a centered 1200px content container (max-width:1200px; margin:auto; padding-inline:clamp(20px,3vw,40px)). Narrow 720px measure for body copy inside splits and FAQ. Card grids sit inside the standard container; the header spans full width with inner container.","columnRatios":["12-column base grid inside 1200px container","about/narrative splits 5:7 and 7:5 image:copy","services rows 4-across, 2-across wide, remainder","FAQ 5:7 illustration:accordion","footer multi-column 4/3/3/2"]},"spacingRhythm":"Section padding is generous and rhythmic: clamp(64px,8vw,110px) between major light sections; the services collection (region-5 analogue) keeps larger internal row gaps (48-64px) to sustain its ~1.86-viewport height; hero is viewport-height driven; newsletter band is compact (~120px vertical padding); footer uses tight 32-40px column spacing with a black banner pad of ~64px. Tokens: --space-2xs 8px, --space-xs 12px, --space-sm 16px, --space-md 24px, --space-lg 40px, --space-xl 64px, --space-2xl clamp(64px,8vw,110px).","typographyRoles":[{"role":"display_xl / h1","description":"Figtree (Google Fonts) 700, clamp(38px,4.2vw,60px) / line-height 1.3, capitalize transform, on dark hero, white text, max-width ~14ch paired to reference line count."},{"role":"h2","description":"Montserrat 700, clamp(30px,2.8vw,40px) / 1.2, letter-spacing 0.8px, capitalize; titles every major section, usually preceded by a small violet pill badge label."},{"role":"h3 / card-title","description":"Figtree 700, clamp(24px,2.4vw,40px) / 1.15, letter-spacing 0.8px; used for sub-headings in splits and service card titles, creating the compressed mid hierarchy."},{"role":"body","description":"Poppins 400, 16px / 1.4, rgb(55,65,81); measure 60-72ch max in splits, narrower (~50ch) in cards."},{"role":"nav / button / badge","description":"Poppins 600, 15px, capitalize; nav links in header strip, pill CTA labels, small pill badges above section headings (12-13px variant allowed)."},{"role":"metadata / chips","description":"Poppins 500-600, 13-14px; floating metric/label chips and footer column headings (Montserrat 600 14px uppercase-adjacent)."}],"colorRoles":[{"role":"dominant surface","description":"Light neutral rgb(249,250,251)/rgb(240,240,240) carries most of the page; violet is never used as a flood."},{"role":"dark anchors","description":"Near-black rgb(16,16,16) for the contact banner and near-black/dark-gray for the footer; dark violet wash rgb(48,32,64) for the hero overlay."},{"role":"primary accent","description":"Exact client-family violet #8E2DE2 for pill CTAs, badges, FAQ pills, icon chips; hover deepens toward #7B24C9 / #4E2FDA. Frequency stays low-to-mid, matching reference distribution."},{"role":"secondary accent","description":"#4E2FDA for secondary emphasis, focus ring, link hover and gradient pairing on hero wash."},{"role":"tint accents","description":"Faint lavender tint rgb(240,224,255) for select section backgrounds and the portrait blob mask fill."},{"role":"text","description":"#111827 headings, #374151 body, #FFFFFF on dark surfaces and inside violet pills."}],"surfaceLanguage":"Flat, friendly SaaS surfaces: no glassmorphism, no heavy gradients beyond the hero's dark violet photographic wash. White rounded cards (16px radius, soft 0 6px 24px rgba(17,24,39,0.08) shadows) on light gray/lavender-tinted bands; pill geometry (999px radius) for all buttons, badges and FAQ rows; 12px-radius icon chips; one full-bleed photographic mass with dark overlay; thin subtle borders on newsletter inputs; no textures or clip art beyond the flat illustration montage in the FAQ.","headerNavigation":"Header (~143px desktop, compressing on mobile): logo left within the 1200px container; centered inline navigation strip (~568px class) of capitalize 15px/600 Poppins links (Home, Services, Process, About, FAQ, Contact set drawn from RankForge pages); distinct violet pill CTA pinned right ('Request an SEO Consultation'). Light surface, subtle bottom border, no transparency-over-hero blending unless the hero directly follows. Mobile: compact header, hamburger opening a panel that keeps the pill CTA reachable; no nav items dropped.","homepageFirstViewport":{"summary":"Header plus hero region as one compositional unit: full-bleed ~1.07-viewport dark violet photographic hero (collaborative office imagery under rgb(48,32,64)-family wash, rgba(48,32,64,0.72) overlay) carrying the Figtree 60px-class display headline 'Get found when your customers are already searching.', supporting copy on technical SEO / content strategy / focused execution, primary violet pill CTA 'Request an SEO Consultation' and secondary pill 'Explore Our Services'. Text block left-weighted, headline max ~14ch per line, CTA row beneath; next region's light surface peeks at the fold on shorter viewports.","regionIds":["region-hero"]},"homepageRegions":[{"id":"region-header","purpose":"Header bar with logo, centered inline nav strip and right violet pill CTA; collapses to compact mobile menu.","sourceEvidenceRegionIds":["region-0","region-1"]},{"id":"region-hero","purpose":"Full-bleed dark violet photographic hero with display headline 'Get found when your customers are already searching.', supporting copy, primary CTA 'Request an SEO Consultation' and secondary 'Explore Our Services'.","imageRoleId":"role-hero-backdrop","sourceEvidenceRegionIds":["region-2"]},{"id":"region-about-split","purpose":"Near-full-height light editorial split: masked portrait photo in lavender blob left, dense bullet copy right introducing RankForge's approach and positioning ('SEO built around commercial growth, not vanity metrics.').","imageRoleId":"role-about-portrait","sourceEvidenceRegionIds":["region-3"]},{"id":"region-trusted-strip","purpose":"Light strip with centered Montserrat heading and a reduced-weight horizontal row of partner/platform-type marks or sector labels appropriate to an SEO agency; no fabricated client logos — desaturated generic marks or capability keywords preserving the strip's quiet rhythm.","sourceEvidenceRegionIds":["region-4"]},{"id":"region-services-collection","purpose":"The page's tallest region (~1.86 viewports): asymmetric card collection presenting exactly the six RankForge services — 4-across icon-chip row, 2-across wide row, remainder row; white rounded cards, 56px icon chips, small violet pill action per card.","imageRoleId":"role-service-icons","sourceEvidenceRegionIds":["region-5"]},{"id":"region-narrative-split-1","purpose":"Narrative split, image right: customer-problem narrative (little qualified traffic, competitors ranking above) with floating label chips carrying the four process stages Diagnose/Prioritise/Execute/Improve instead of fabricated metrics.","imageRoleId":"role-narrative-shot-a","sourceEvidenceRegionIds":["region-6"]},{"id":"region-narrative-split-2","purpose":"Narrative split, image/illustration montage left: the four-stage process narrative with floating chips for stage names, preserving the reference's floating-chip-over-imagery composition.","imageRoleId":"role-narrative-shot-b","sourceEvidenceRegionIds":["region-7"]},{"id":"region-faq","purpose":"Light FAQ band: flat illustration montage left, right-stacked pill accordion rows (first expanded dark, rest saturated violet pills with chevrons) answering RankForge service/process questions.","imageRoleId":"role-faq-illustration","sourceEvidenceRegionIds":["region-8"]},{"id":"region-photo-cards","purpose":"Full-bleed office-photograph backdrop with white rounded overlay cards and dark accent card left, carrying RankForge's closing positioning/engagement framing (no invented testimonials) inside the reference card geometry.","imageRoleId":"role-photo-backdrop","sourceEvidenceRegionIds":["region-9"]},{"id":"region-newsletter","purpose":"Compact newsletter band with inline name/email fields inviting RankForge search-growth updates; form submits via the WAZIBIZ Form Service.","sourceEvidenceRegionIds":["region-10"]},{"id":"region-contact-footer","purpose":"Black full-width contact banner with 'Ready to make organic search work harder for your business?' and CTA 'Talk to RankForge', flowing into a dense dark multi-column footer with services links, navigation, and hello@rankforgekenya.example (WAZIBIZ Form Service handles all submissions).","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Documentary-commercial business photography: candid collaborative office/workplace scenes, one-to-two people, task-focused or lightly posed, natural daylight, soft-to-moderate contrast, warm-neutral to slightly warm character. Hero and backdrop imagery is darkened under violet/near-black overlays for text safety. Portrait about image is a medium shot of one person at a device inside a soft lavender blob mask. Narrative imagery pairs medium posed-person shots with floating chips. No macro product shots, no dramatic cinematic lighting, no desaturated editorial treatment. All subjects must be generic business/office contexts — never copied reference people or branding.","imageRoles":[{"id":"role-hero-backdrop","purpose":"Darkened collaborative-office scene (people at laptops, wide environmental) behind the hero headline and CTAs; wide landscape 16:9 minimum, text-safe left zone under violet/near-black wash.","priority":"CRITICAL"},{"id":"role-about-portrait","purpose":"Portrait-orientation medium shot of one professional at a device, displayed inside a soft lavender blob/circle mask in the about split; ~2:3 ratio.","priority":"CRITICAL"},{"id":"role-service-icons","purpose":"Small square flat icon/illustration chips (~56px) topping each service card, one per RankForge service, consistent flat style in violet family.","priority":"HIGH"},{"id":"role-narrative-shot-a","purpose":"Medium shot of a single person with laptop against clean light/lavender background, right-aligned in narrative split one, with clearance for floating chips.","priority":"HIGH"},{"id":"role-narrative-shot-b","purpose":"Medium shot or light photo/illustration montage of analysis/work context, left-aligned in narrative split two with chip clearance.","priority":"HIGH"},{"id":"role-faq-illustration","purpose":"Flat colorful illustration montage figures beside the FAQ accordion, square-ish, violet-family palette.","priority":"NORMAL"},{"id":"role-photo-backdrop","purpose":"Full-bleed real-office photograph (people collaborating) behind overlay cards in the photo-card region; wide landscape, darkened ~0.55 for card readability.","priority":"CRITICAL"}]},"motionGrammar":["Scroll-triggered reveal transitions (fade + small upward travel, 250-450ms) substitute the reference's heavy parallax per the Adaptation Contract; sections and cards animate in once.","Focal motion: floating chips in narrative splits receive a subtle delayed drift/scale reveal, echoing the reference's parallax focal elements without scroll-linked movement.","Hero and photo-backdrop imagery remain static (no parallax); depth is conveyed via overlay and shadow.","Violet pill buttons: background deepen and slight shadow lift on hover, 200ms ease-primary; focus-visible ring always.","FAQ accordion rows expand/collapse 250ms with chevron rotation; first item open by default.","prefers-reduced-motion: all reveals, drifts and transitions reduced to opacity-only or removed; content and focus states fully preserved."],"responsiveContract":["Breakpoints: 1440 desktop reference, 1024 intermediate, 768, 375 mobile; content never removed at any width.","Header compresses from 143px; centered nav strip collapses to a compact menu panel keeping the pill CTA reachable.","Services card rows: 4-across → 2-across → single-column stacked cards, each retaining icon chip and pill CTA.","Splits (about, narrative 1/2, FAQ) stack image above copy on narrow viewports; portrait scales within its blob mask.","Full-bleed hero and photo-backdrop regions crop imagery (object-fit: cover, focal recentering) while retaining overlay text/card composition.","Trusted strip wraps or scrolls to a smaller set on mobile.","Newsletter band fields stack vertically on mobile; footer columns collapse to stacked groups.","No horizontal overflow at 375px; minimum body type 16px; touch targets ≥44px."],"innerPageVocabulary":["EDITORIAL_SPLIT: image one side (optionally blob-masked), copy other — About page lead, services detail sections.","NARROW_NARRATIVE: 720px centered measure for philosophy/principles text — About 'SEO without the noise.' principles.","CARD_GRID_4_2: 4-across then 2-across white icon-chip cards — services index and audit breakdowns.","PROCESS_SEQUENCE: numbered 01–04 stage rows with pill chips — RankForge process pages.","QUIET_CTA: full-width near-black banner with headline and violet pill CTA — page closers.","CONTACT_SPLIT: form (Name, Company, Email, Phone, Website, help-topic select, Message) beside supporting copy — Contact page.","FAQ_ACCORDION_BAND: violet pill accordion beside illustration — service FAQs."],"antiFallbackRules":["Do not flatten the services collection into a uniform 3-across grid or shorten it to one row; preserve the 4/2/remainder asymmetric rhythm and its tall scale.","Do not replace violet pill buttons with rectangular or outlined generic buttons; pill geometry with trailing arrow/plus glyphs is systemic.","Do not center all headings; H2s follow reference alignment per region.","Do not remove the black contact banner or the compact newsletter band; both are identity carriers.","Do not drop the floating-chip visual in narrative splits, even though chips carry process labels rather than invented metrics.","Do not add gradients, glassmorphism, or heavy shadows absent from the reference.","Do not replace the photo-backed card region with a plain card row on a flat surface; the photographic backdrop mass is mandatory.","Do not copy reference business content, logos, testimonials or imagery; Reference is design evidence only, and no invented metrics, testimonials, awards or statistics may appear."],"accessibilityAdaptations":["All violet pill CTAs use white text meeting 4.5:1 against #8E2DE2-class fills; hover states deepen contrast.","Hero and backdrop overlays tuned so overlaid text/cards meet contrast requirements on the darkened imagery.","Focus-visible rings (#4E2FDA, 2px offset) on all interactive elements including accordion rows and newsletter inputs.","Accordion uses button elements with aria-expanded/aria-controls; newsletter and contact forms have labelled fields and WAZIBIZ Form Service validation messaging.","prefers-reduced-motion removes reveal travel, chip drift and parallax substitutes while preserving all content.","Responsive type never below 16px body; no hover-only essential behavior; mobile nav fully keyboard operable."],"declaredLimitations":["heavy_parallax: reference scroll-linked parallax choreography replaced by reveal transitions and depth cues per accepted Adaptation Contract (feature token 'mass:region-2'/'mass:region-9' parallax components adapted statically).","Photo-backed testimonial cards carry RankForge positioning/engagement content instead of invented testimonials (content constraint), preserving the composition, backdrop mass and card geometry.","Floating metric chips carry process-stage labels instead of fabricated percentages (no-statistics constraint).","Trusted-logos strip uses generic desaturated capability marks or sector labels rather than fabricated client logos.","Exact reference font files approximated with Figtree/Montserrat/Poppins from Google Fonts; measured timing/easing values were unavailable so standard 250ms easing is used.","Icon-chip illustrations are generated flat violet-family icons approximating the reference's illustration style, not copies."]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":2,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5826,"completion_tokens_details":{"reasoning_tokens":164},"prompt_tokens":16291,"prompt_tokens_details":{"cached_tokens":0},"total_tokens":22117}},"createdAt":"2026-09-06T17:38:38.442Z"}},{"runId":"2fdaa867-4e76-4dc5-87c4-9de719a39172","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A friendly SaaS-style digital-agency system for RankForge Kenya: full-bleed dark-violet photographic hero (~1.07 viewport) with 60px display headline and violet pill CTA, framed by a floating centered pill navigation bar; a predominantly light neutral body (rgb(240,240,240) with faint lavender tints) of badge-titled sections; a near-full-height about split with a lavender blob-masked portrait; a very tall asymmetric six-service card collection with icon chips and per-card violet pill CTAs; narrative splits with floating stat-chip overlays; a violet pill accordion FAQ beside flat illustration montage; photo-backed testimonial band; compact newsletter strip; and a black contact banner merging into a dense dark multi-column footer. Violet pill buttons, badges and accent chips carry all actions; alternating dark/light surface masses sequence the page top to bottom.","signatureTraits":[{"id":"trait-dark-violet-photo-hero","sourceTraitId":"dark-violet-photo-hero","description":"Full-bleed ~964px hero with photographic background under a dark violet/purple wash (dominant rgb(48,32,64) family), containing the 60px display headline and a violet pill CTA. RankForge substitution: hero shows a darkened collaborative-work/search-analytics environment; headline 'Get found when your customers are already searching.' with CTA 'Request an SEO Consultation'. No reference text or imagery copied."},{"id":"trait-floating-pill-nav-cta","sourceTraitId":"floating-pill-nav-cta","description":"Header bar with a centered inline pill navigation strip (measured 568x25px at desktop) of 15px/600 capitalize links, plus a distinct violet pill CTA ('Request an SEO Consultation') at the header's right, kept visually reachable on mobile."},{"id":"trait-about-split-portrait","sourceTraitId":"about-split-portrait","description":"Near-full-height (~870px) light editorial split: large portrait-orientation medium shot (natural ~1000x1500) displayed ~500px wide inside a soft lavender circular/blob mask on the left, dense multi-bullet copy on the right. RankForge substitution: portrait of a person doing analytical SEO work (search console/analytics on screen), bullets describing approach and principles."},{"id":"trait-very-tall-card-collection","sourceTraitId":"very-tall-card-collection","description":"Single tallest region (~1670px, ~1.86 viewport ratios) holding an asymmetric card collection: a 4-across icon-card row, then a 2-across wide-card row, then another 4-across row; equal white rounded cards with small violet pill action buttons under each. RankForge substitution: the six services distributed across this row rhythm (4 / 2 / folded as needed) with icon chips — no invented stats or results."},{"id":"trait-narrative-split-with-stat-chips","sourceTraitId":"narrative-split-with-stat-chips","description":"Two sequential narrative splits (one right-aligned image, one left-aligned) pairing medium shots of people with copy and small floating chip cards. RankForge adaptation: chips carry the four process stages (01 Diagnose / 02 Prioritise / 03 Execute / 04 Improve) and problem→approach labels — never fabricated metrics, since quantitative claims are prohibited."},{"id":"trait-accordion-faq-light-band","sourceTraitId":"accordion-faq-light-band","description":"A ~761px light FAQ band with flat illustration montage on the left and right-stacked violet pill-shaped accordion rows; first item expanded in dark text, the rest as saturated violet pills with trailing chevron icons. RankForge substitution: service-related questions (scope, engagement, local SEO, audits)."},{"id":"trait-photo-backed-testimonials","sourceTraitId":"photo-backed-testimonials","description":"A full-bleed real-office photograph band (extraction imageMass 1440x630, density 0.789) with white rounded cards and a dark accent quote card overlaying the left half. RankForge adaptation: no testimonials may be invented — this region's visual mass is preserved as a photo-backed trust/value band with white cards carrying positioning statements and service capabilities, dark accent card carrying the closing proposition. Trait's visual role (photo-backed overlaid card composition) is retained."},{"id":"trait-compact-newsletter-dark-contact-footer","sourceTraitId":"compact-newsletter-dark-contact-footer","description":"A compact ~341px newsletter band with inline fields, followed by a ~721px dark footer region beginning with a black full-width contact banner (rgb(16,16,16)) and a dense multi-column dark footer. RankForge substitution: closing CTA 'Ready to make organic search work harder for your business?' / 'Talk to RankForge', contact email hello@rankforgekenya.example, Nairobi/Kenya service framing."}],"fidelityPriorities":["1. Page silhouette and 12-region surface sequencing (dark hero → light bands → photo mass → dark anchors) — the strongest identity carrier.","2. First viewport: full-bleed dark-violet photographic hero with 60px display headline and pill CTA.","3. Very tall asymmetric services card collection (~1.86 viewport ratios) with icon chips and pill CTAs.","4. Violet pill button/badge/accordion system as the sole action language.","5. Three-family typography stack (Figtree display / Montserrat H2 / Poppins body) with capitalize heading voice.","6. Masked portrait about split and narrative splits with floating chips.","7. Photo-backed testimonial band and compact newsletter + black contact banner + dark footer close.","8. Mobile single-column reflow preserving all sections, pill CTAs and overlay compositions."],"tokens":{"brand_primary":"#8E2DE2","brand_secondary":"#4E2FDA","brand_primary_hover":"#7A21C8","brand_accent_soft":"#F0E0FF","surface_body":"#F9FAFB","surface_light":"#F0F0F0","surface_lavender_tint":"#F0E0FF","surface_dark_band":"#101010","surface_footer_dark":"#505050","surface_footer_deep":"#403030","surface_card":"#FFFFFF","text_primary":"#374151","text_on_dark":"#F5F3FF","text_muted":"#6B7280","overlay_hero_violet":"rgba(48,32,64,0.72)","overlay_photo_dark":"rgba(16,16,16,0.55)","radius_pill":"999px","radius_card":"16px","radius_icon_chip":"12px","border_subtle":"1px solid rgba(55,65,81,0.12)","shadow_card":"0 8px 24px rgba(16,16,16,0.08)","shadow_chip":"0 6px 18px rgba(78,47,218,0.18)","motion_fast":"150ms","motion_standard":"300ms","motion_reveal":"600ms","ease_primary":"cubic-bezier(0.4, 0, 0.2, 1)","container_max":"1280px","container_narrow":"760px","gutter_desktop":"40px","gutter_mobile":"20px","space_section_normal":"clamp(64px, 8vw, 112px)","space_section_tight":"clamp(40px, 5vw, 64px)","type_display":"Figtree 700, clamp(38px, 4.2vw, 60px)/1.3, capitalize","type_h2":"Montserrat 700, clamp(28px, 2.8vw, 40px)/1.2, letter-spacing 0.8px, capitalize","type_feature":"Figtree 700, clamp(24px, 2.2vw, 32px)/1.25, letter-spacing 0.8px","type_body":"Poppins 400, 16px/1.4","type_ui":"Poppins 600, 15px, capitalize"},"globalGrid":{"containerLogic":"Full-bleed section surfaces spanning 100vw with an inner content container of max-width 1280px and 40px desktop gutters (20px mobile). Hero, testimonial backdrop and black contact banner are full-bleed escapes; all card grids, splits and forms live inside the container. No additional width systems — the reference uses one consistent container with full-bleed surface escapes.","columnRatios":["12-column base grid, gap 24px","About/narrative splits: 5/7 and 7/5 image-copy ratios","Card rows: 4-across equal, 2-across wide","FAQ: 4/8 illustration-to-accordion","Newsletter: single inline row, 3 fields + submit"]},"spacingRhythm":"Editorial long-scroll rhythm: dark hero ~964px, about split ~870px, services collection ~1670px, narrative regions ~700–870px, FAQ ~761px, testimonial band ~430–630px, newsletter ~341px, footer ~721px. Section padding token clamp(64px, 8vw, 112px) top/bottom; tight bands (newsletter, logo strip) use clamp(40px, 5vw, 64px). Internal grid gap 24px; card internal padding 24–32px. Do not normalize the intentionally tall services region or compact newsletter.","typographyRoles":[{"role":"display_xl / h1","description":"Figtree 700, 60px/78px desktop, capitalize, white on dark hero; scales to ~38px mobile; single- to two-line maximum."},{"role":"h2","description":"Montserrat 700, 40px/48px, letter-spacing 0.8px, capitalize; titles every major section, usually preceded by a small violet pill badge label (15px Poppins 600 capitalize)."},{"role":"feature_heading","description":"Figtree 700 bold paragraph-role at 40px/40px desktop (min 24px mobile), letter-spacing 0.8px, for card titles and sub-headings inside splits — a deliberately compressed hierarchy level below H2."},{"role":"body","description":"Poppins 400, 16px/22.4px, sentence case, max measure ~65ch, rgb(55,65,81) on light surfaces."},{"role":"nav / button / badge","description":"Poppins 600, 15px, capitalize, used for nav links, pill CTA labels, badges and FAQ pill rows; trailing arrow/plus/chevron glyphs on buttons and accordions."}],"colorRoles":[{"role":"primary accent (violet)","description":"Saturated violet #8E2DE2 with deep violet #4E2FDA: all CTA pill fills, badge pills, FAQ pill rows, icon chips, links. Low-to-mid frequency — reserved for actions and accents, never large surfaces."},{"role":"dark violet hero wash","description":"Dark purple overlay family (rgb(48,32,64)–rgb(96,64,112)) over hero photography, ensuring white display type contrast."},{"role":"light neutral body surfaces","description":"Body rgb(249,250,251) and section surfaces rgb(240,240,240) with faint lavender tints (rgb(240,224,255)) on selected bands (services, FAQ vicinity)."},{"role":"dark anchor surfaces","description":"Near-black rgb(16,16,16) contact banner and dark footer bands rgb(80,80,80)/rgb(64,48,48) framing the page close; white/near-white text on these."},{"role":"text and neutrals","description":"Primary text rgb(55,65,81); white cards; subtle 12%-alpha borders; white pill CTAs invert to violet-on-light where needed for contrast."}],"surfaceLanguage":"Flat, friendly SaaS depth: white rounded cards (16px radius) with soft diffuse shadows on light gray bands; fully rounded pill geometry for every button, badge and accordion row (999px radius); icon chips at ~12px radius; full-bleed photographic surfaces flattened by dark violet/near-black overlays rather than gradients; faint lavender-tinted bands as surface variation; no glass, no glassmorphism, no decorative gradients beyond overlay washes. Surface shifts — dark hero → light bands → lavender tints → photo mass → near-black band → dark footer — do the sequencing work.","headerNavigation":"Header bar ~143px desktop containing logo left, the centered inline pill navigation strip (~568px, Poppins 15px/600 capitalize links: Services, Process, About, Contact) and a violet pill CTA 'Request an SEO Consultation' at the right. Light surface over the dark hero or transparent-over-hero with legible links; compresses on scroll; collapses to a compact mobile menu below tablet width while keeping the pill CTA reachable (visible button or within opened menu).","homepageFirstViewport":{"summary":"First viewport = compact header (~143px with nav strip and pill CTA) + full-bleed ~964px dark-violet photographic hero: background photograph of collaborative analytical work darkened by a violet wash (dominant rgb(48,32,64)); left-aligned 60px Figtree display headline 'Get found when your customers are already searching.', short supporting copy on technical SEO, content strategy and focused search execution; primary violet pill CTA 'Request an SEO Consultation' and secondary quiet link/outline pill 'Explore Our Services'. Text sits in text-safe negative space of the image; hero slightly exceeds one viewport height (target ratio ~1.07, acceptable 0.9–1.2).","regionIds":["region_hero"]},"homepageRegions":[{"id":"region_hero","purpose":"Header bar + centered pill nav strip + full-bleed dark-violet photographic hero with display headline, supporting copy, primary pill CTA 'Request an SEO Consultation' and secondary 'Explore Our Services'.","imageRoleId":"img_hero_dark_office","sourceEvidenceRegionIds":["region-0","region-1","region-2"]},{"id":"region_about_split","purpose":"Near-full-height light editorial split: lavender blob-masked portrait of RankForge analytical work on the left, dense multi-bullet 'SEO without the noise' approach copy and principles on the right, H2 with violet pill badge.","imageRoleId":"img_about_portrait","sourceEvidenceRegionIds":["region-3"]},{"id":"region_services_collection","purpose":"Very tall (~1.86 viewport) asymmetric services collection presenting the six RankForge services as white rounded cards with icon chips and per-card violet pill buttons, in 4-across / 2-across wide / 4-across row rhythm under a badge-titled H2.","imageRoleId":"img_service_icon_chips","sourceEvidenceRegionIds":["region-5"]},{"id":"region_logos_strip","purpose":"Light strip with centered Montserrat heading and a horizontal row of low-weight marks. RankForge adaptation: no client logos may be invented — the strip carries desaturated sector/service-domain labels (e.g. 'SMEs · Ecommerce · Hospitality · B2B · Professional Services') at reduced visual weight, preserving the strip's composition.","sourceEvidenceRegionIds":["region-4"]},{"id":"region_narrative_split_a","purpose":"Narrative split with right-aligned photo of a person at work and copy describing the customer problem (little qualified traffic, competitors ranking above), plus floating chip cards carrying process-stage labels (no fabricated metrics).","imageRoleId":"img_narrative_person_a","sourceEvidenceRegionIds":["region-6"]},{"id":"region_narrative_split_b","purpose":"Mirrored narrative split (left-aligned image/illustration montage) with copy on the four-stage process — Diagnose, Prioritise, Execute, Improve — using floating chips labeled 01–04 instead of metric values.","imageRoleId":"img_narrative_person_b","sourceEvidenceRegionIds":["region-7"]},{"id":"region_faq","purpose":"Light FAQ band: flat illustration montage left, right-stacked violet pill accordion rows (first expanded in dark text, rest saturated violet pills with chevrons) answering service-scope questions.","imageRoleId":"img_faq_illustration","sourceEvidenceRegionIds":["region-8"]},{"id":"region_photo_backed_trust","purpose":"Full-bleed real-office photograph backdrop with white rounded cards and a dark accent card overlaying the left half, carrying RankForge value statements and service capabilities (no invented testimonials), echoing the reference's proof-band composition.","imageRoleId":"img_office_backdrop","sourceEvidenceRegionIds":["region-9"]},{"id":"region_newsletter","purpose":"Compact ~341px light band with inline name/email fields and violet pill submit, inviting SEO updates/consultation follow-up; forms submit via the WAZIBIZ Form Service.","sourceEvidenceRegionIds":["region-10"]},{"id":"region_contact_footer","purpose":"Black full-width contact banner ('Ready to make organic search work harder for your business?' + pill CTA 'Talk to RankForge') transitioning into a dense dark multi-column footer with navigation, contact email hello@rankforgekenya.example and Nairobi, Kenya service framing.","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Environmental business-context photography, not product display. Candid/lightly-posed medium shots of one to two people working at laptops and devices in clean, modern Nairobi office environments; warm-neutral to slightly warm color character with moderate contrast; dark violet washes over full-bleed hero and trust-band photography so overlaid UI stays readable; one large portrait-orientation about image inside a soft lavender blob mask; small flat colorful icon/illustration chips for service cards and FAQ montage. Backgrounds restrained and text-safe where copy overlaps. Avoid: macro product shots, dramatic cinematic lighting, desaturated editorial treatment, generic handshake stock poses, visible generated text or logos.","imageRoles":[{"id":"img_hero_dark_office","purpose":"Full-bleed darkened collaborative-work/search-analytics office scene as hero backdrop supporting white display headline and pill CTA; text-safe negative space left-of-center; landscape, ~16:9 minimum, CRITICAL.","priority":"CRITICAL"},{"id":"img_about_portrait","purpose":"Portrait-orientation (2:3) medium shot of a single person doing analytical SEO work (screens with rankings/analytics), displayed ~500px wide inside a soft lavender circular/blob mask; HIGH.","priority":"HIGH"},{"id":"img_service_icon_chips","purpose":"Six small flat, colorful icon/illustration chips (~56–90px) for the service cards: strategy, technical, local, content, ecommerce, audit; square, consistent flat illustration style; HIGH.","priority":"HIGH"},{"id":"img_narrative_person_a","purpose":"Medium shot, person at laptop with floating chip overlays, right-aligned in first narrative split; landscape ~4:3; HIGH.","priority":"HIGH"},{"id":"img_narrative_person_b","purpose":"Medium shot or light photo/illustration montage, person with tablet or planning board, left-aligned in second narrative split with 01–04 chips; landscape ~4:3; NORMAL.","priority":"NORMAL"},{"id":"img_faq_illustration","purpose":"Flat illustration montage figures (~90px, square) beside the FAQ accordion, matching service-chip illustration style; NORMAL.","priority":"NORMAL"},{"id":"img_office_backdrop","purpose":"Full-bleed real-office photograph backdrop (1440x630-class panoramic crop) for the photo-backed trust band, moderately darkened under overlaid white and dark accent cards; CRITICAL.","priority":"CRITICAL"}]},"motionGrammar":["Scroll-triggered reveal transitions (fade + small translate-up, ~600ms, ease cubic-bezier(0.4,0,0.2,1)) for sections and card rows; staggering across card grids.","Floating process chips in narrative splits receive a subtle slower drift/depth cue replacing the reference's heavy parallax per the Adaptation Contract; hero and trust-band backgrounds get a reduced parallax cue at most.","Violet pill buttons: background darken + slight shadow lift on hover (150ms); FAQ accordion rows expand/collapse (~300ms) with rotating chevron.","No structural scroll motion: no horizontal scroll, no section reordering; topology stable under scroll.","prefers-reduced-motion: reveals render as simple opacity or none; parallax/drift disabled; hover feedback reduced to instant color change; all content and focus states remain visible."],"responsiveContract":["All 12 canonical regions retained on mobile — single-column stacking, no content removal.","Card rows (4-across, 2-across) collapse to stacked single-column cards, each retaining icon chip and pill CTA.","Split regions stack image above copy; the blob-masked portrait scales down within its mask.","Centered nav strip collapses to a compact mobile menu; header compresses; pill CTA remains reachable.","Full-bleed photo regions (hero, trust band) crop imagery while retaining overlay cards and headline stacking.","Logo/sector strip wraps or scrolls into a smaller set.","No horizontal overflow at 375px; touch targets ≥44px; type scales via clamp tokens."],"innerPageVocabulary":["EDITORIAL_SPLIT: badge-titled H2 + masked image / dense bullets — About lead pattern.","NARROW_NARRATIVE: 760px measure text block with small violet badge heading — philosophy/principles.","CARD_GRID_SERVICES: 3-across white rounded cards with icon chips and per-card pill CTAs — Services index (six services).","SERVICE_DETAIL_SPLIT: 5/7 image-copy detail with pill CTA — individual service pages.","PROCESS_SEQUENCE: numbered 01–04 stages as cards or stacked rows with chips — process content.","CONTACT_SPLIT: black contact banner + inline form (Name, Company, Email, Phone, Website, help-topic select, Message) with violet pill submit — Contact.","QUIET_CTA_BAND: compact violet-on-light or dark banner CTA closing inner pages."],"antiFallbackRules":["Do not erase the violet pill button system: every CTA, badge and FAQ row must remain rounded-pill violet geometry with trailing glyphs.","Do not shorten the services collection into a single tidy 3-card row — preserve the tall asymmetric 4/2/4 row rhythm with six services mapped in.","Do not replace the dark-violet photographic hero with a flat color or gradient hero.","Do not remove the lavender blob mask from the about portrait.","Do not convert the accordion FAQ into plain text lists; keep pill rows with chevrons.","Do not drop the photo-backed trust band despite no invented testimonials — keep the photo-backed overlaid-card composition with permitted content.","Do not invent client logos, metrics, testimonials or results anywhere.","Do not add gradients, glass, or heavy shadows absent from the reference; keep flat friendly card depth.","Do not drop the black contact banner; it must precede the dark footer."],"accessibilityAdaptations":["White text on dark violet hero wash and black banner meets WCAG AA contrast; violet pill fills use white 15px/600 labels verified against #8E2DE2/#4E2FDA (AA large/bold; darken to #7A21C8 where needed).","Visible focus rings on all pills, nav links, accordion buttons and form fields.","Accordion implemented as accessible disclosure buttons with aria-expanded; no hover-only behavior.","Reduced-motion fallback per motion grammar; no parallax dependency for comprehension.","Mobile type ≥16px body; no horizontal overflow; 44px touch targets; form labels programmatically associated."],"declaredLimitations":["Heavy scroll-linked parallax replaced by reveal transitions and subtle depth cues per Adaptation Contract (feature token 'mass:parallax-choreography').","No testimonials, client logos, metrics or results inventable: logo strip carries sector labels; photo-backed trust band carries value statements in the reference's card composition (adaptation token 'mass:region-9').","Exact reference fonts assumed available via Google Fonts (Figtree, Montserrat, Poppins); fallback to closest geometric sans if unavailable.","Measured timing/easing values unavailable; motion durations are best-practice estimates.","Floating metric chips are adapted to process-stage chips because quantitative claims are prohibited by Business Facts."]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":1,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5830,"completion_tokens_details":{"reasoning_tokens":33},"prompt_tokens":16238,"prompt_tokens_details":{"cached_tokens":16192},"total_tokens":22068}},"createdAt":"2026-09-06T18:18:06.382Z"}},{"runId":"5cdda754-48a9-44bf-869e-6b0780534e81","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A long-scroll, SaaS-style B2B agency page that alternates a dark violet photographic hero, predominantly light neutral surfaces with faint lavender tints, one photographic proof band and dark anchor bands at the page end. Identity is carried by a violet pill button/badge system, a three-family type stack (rounded-geometric display, tracked grotesque H2, humanist body with capitalize transforms), an unusually tall asymmetric card collection for the six services, narrative splits with floating descriptive chips, a pill-accordion FAQ, and a compact newsletter band leading into a black contact banner and dense dark footer. For RankForge Kenya, all reference branding and content are replaced with Nairobi SEO-growth agency content; violet accent roles are preserved as the brand's primary accent color system.","signatureTraits":[{"id":"dark-photo-hero-violet-wash","description":"Full-bleed ~1.07-viewport hero (evidence region-2) with photographic office/collaboration background under a dark violet wash, carrying the 60px-class display headline and one violet pill CTA. Implementation: darkened image with rgb(48,32,64)-family overlay, white display headline, single pill CTA 'Request an SEO Consultation' plus secondary text CTA.","sourceTraitId":"dark-violet-photo-hero"},{"id":"centered-pill-nav","description":"Header bar (~143px desktop) with centered inline navigation strip (Poppins-class 15px/600 capitalize links) and a distinct violet pill CTA at the header right. Mobile collapses to a compact menu keeping the pill CTA reachable.","sourceTraitId":"floating-pill-nav-cta"},{"id":"masked-portrait-about-split","description":"Near-full-height light editorial split: large portrait-orientation photo in a soft lavender circular/blob mask on the left, dense multi-bullet copy on the right, titled with a violet pill badge + tracked H2. For RankForge: portrait of a practitioner at work on SEO analysis.","sourceTraitId":"about-split-portrait"},{"id":"tall-asymmetric-service-collection","description":"The tallest region (~1.86 viewport ratios) holds RankForge's six services as an asymmetric card collection: a 4-across icon-chip card row, a 2-across wide-card row, then a further row — equal white rounded cards with small violet pill per-card actions. No card invented beyond the six verified services; wide cards carry the two deepest services (SEO Strategy, SEO Audits).","sourceTraitId":"very-tall-card-collection"},{"id":"narrative-split-with-floating-chips","description":"Two sequential narrative splits pairing imagery with copy plus small floating cards. Because business facts prohibit invented statistics, chips carry descriptive labels (e.g. 'Technical SEO', 'Local SEO — Nairobi', 'Content Strategy') rather than metrics. First split right-aligned image, second left-aligned image, alternating.","sourceTraitId":"narrative-split-with-stat-chips"},{"id":"pill-accordion-faq","description":"Light FAQ band with left flat-illustration montage and right-stacked violet pill-shaped accordion rows: first item expanded in dark text, remaining items as saturated violet pills with trailing chevron icons.","sourceTraitId":"accordion-faq-light-band"},{"id":"photo-backed-card-band","description":"Full-bleed office photograph band with overlaid white rounded cards and one dark accent card on the left. Adapted for RankForge into a photo-backed 'problems we solve' / closing-conversion band using only verified customer problems — no invented testimonials, ratings or metrics.","sourceTraitId":"photo-backed-testimonials"},{"id":"newsletter-dark-contact-footer","description":"Compact ~0.4-viewport newsletter band with inline name/email fields, then a ~0.8-viewport dark contact/footer region beginning with a black full-width conversion banner ('Ready to make organic search work harder for your business?' + 'Talk to RankForge' pill) and dense multi-column dark footer.","sourceTraitId":"compact-newsletter-dark-contact-footer"}],"fidelityPriorities":["1. Page silhouette and surface sequence (dark hero → light bands → photo mass → dark anchors) — the strongest identity signal.","2. First-viewport composition: darkened photo hero, display headline scale, violet pill CTA.","3. Violet pill button/badge system with trailing glyphs — applied to every action.","4. Region topology and height strategy, including the ~1.86-ratio services collection.","5. Typography relationships: three-family stack, capitalize heading voice, display/body contrast.","6. Photography grammar: darkened collaborative-office backgrounds, masked portrait, medium posed-person shots.","7. Responsive transformations: full stacking without content removal, masked portrait scaling, nav collapse.","8. Motion language: scroll reveals with static composition (per Adaptation Contract)."],"tokens":{"brand_primary":"#8E2DE2","brand_secondary":"#4E2FDA","brand_primary_hover":"#7A22C8","surface_body":"#F9FAFB","surface_light":"#F0F0F0","surface_lavender_tint":"#F0E0FF","surface_dark_banner":"#101010","surface_footer":"#3A3238","hero_wash":"rgba(48,32,64,0.82)","text_primary":"#111827","text_body":"#374151","text_muted":"#6B7280","text_on_dark":"#F5F3F7","border_subtle":"#E5E7EB","focus_ring":"#8E2DE2","radius_card":"16px","radius_pill":"999px","container_max":"1200px","container_narrow":"720px","gutter_desktop":"40px","gutter_mobile":"20px","space_section_normal":"clamp(64px, 8vw, 112px)","space_section_tight":"clamp(40px, 5vw, 64px)","font_display":"Figtree, sans-serif (700)","font_h2":"Montserrat, sans-serif (700, 0.8px tracking)","font_body_ui":"Poppins, sans-serif"},"globalGrid":{"containerLogic":"Full-bleed surface bands with an inner 1200px max-width content container, 40px desktop / 20px mobile gutters. Split regions use two-column grids; card regions use 4-col and 2-col rows inside the same container; dark banner and footer bands are full-bleed surfaces with container-aligned content. No horizontal overflow at any breakpoint.","columnRatios":["1:1 (splits)","5:7 (about split, image lighter)","4-across equal cards","2-across wide cards","5:7 FAQ illustration/accordion"]},"spacingRhythm":"Generous editorial rhythm: normal sections ~96–112px vertical padding, tight bands (newsletter, logo strip) ~56–64px, hero full-viewport height. Consistent ~24–32px internal gaps between heading badge, heading, body and CTAs; 16–24px gaps in card grids; footer uses dense 48px column gutters. Preserve the intentional contrast between the airy hero/about and the compressed newsletter band.","typographyRoles":[{"role":"display_xl (hero H1)","description":"Figtree 700, ~60px/78px desktop scaling to ~34px mobile, capitalize, white on dark hero, max ~14 words over 2–3 lines."},{"role":"h2","description":"Montserrat 700, 40px/48px desktop, 0.8px letter-spacing, capitalize, preceded by small violet pill badge label; scales to ~28px mobile."},{"role":"sub_heading","description":"Figtree 700, ~28–32px desktop, used for card titles and narrative sub-headings, creating a compressed hierarchy below H2."},{"role":"body","description":"Poppins 400, 16px/1.4, rgb(55,65,81), max measure ~65ch; bullet lists in about split use 1.5 line-height."},{"role":"ui_button_badge","description":"Poppins 600, 15px, capitalize, used for nav links, pill CTA labels and badge labels."},{"role":"footer_small","description":"Poppins 400/500, 14px, text-on-dark with muted variants for footer columns and legal line."}],"colorRoles":[{"role":"dominant_light_surfaces","description":"Light neutral #F9FAFB/#F0F0F0 with occasional faint lavender tints #F0E0FF carries the majority of the page; do not flood with brand violet."},{"role":"brand_violet_accent","description":"Saturated violet #8E2DE2 (with deeper #4E2FDA for gradients/variants) is reserved for CTAs, badges, FAQ pills, icon chips — low-to-mid frequency, attention-directing only."},{"role":"dark_anchor_surfaces","description":"Dark violet-washed hero and near-black #101010 contact banner frame the page top and bottom, echoing the reference mass balance."},{"role":"text_hierarchy","description":"Near-black headings, #374151 body, #6B7280 metadata; light-on-dark equivalents in hero, banner and footer."}],"surfaceLanguage":"Flat, friendly SaaS surfaces: white rounded cards (16px radius) on light bands, saturated violet pill fills for actions, soft lavender blob/circular mask for the about portrait, dark gradient wash over photographic hero and testimonial-band imagery, near-black full-bleed banner before the footer. Minimal shadows (subtle card elevation only), no glass, no textures, no gradient buttons beyond subtle violet depth.","headerNavigation":"Static (non-sticky is acceptable; sticky with solid light background is allowed on scroll) ~143px desktop header: logo left, centered inline nav strip of capitalize Poppins 600 links (Home, Services, About, Process, FAQ, Contact), violet pill CTA ('Request an SEO Consultation' shortened, e.g. 'Free Consultation') at the right. Mobile: hamburger opening a compact panel with stacked links and the pill CTA kept visible; header compresses to ~64–72px.","homepageFirstViewport":{"summary":"Header plus a full-bleed dark photographic hero occupying ~1.07 viewport height total. Background: candid collaborative office/workplace photograph under a dark violet wash (rgba(48,32,64,~0.82)) ensuring white text contrast. Content block left-aligned inside the 1200px container: hero headline 'Get found when your customers are already searching.' (Figtree-class 60px/700, capitalize, 2–3 lines), supporting copy on technical SEO, content strategy and focused search execution (~40–60 words, max 560px), then a violet pill primary CTA 'Request an SEO Consultation' with arrow glyph and a secondary text CTA 'Explore Our Services'. Some of the next light band may peek at very tall viewports; bottom of hero anchors with dark mass.","regionIds":["region_hero"]},"homepageRegions":[{"id":"region_hero","purpose":"Header, centered inline nav with violet pill CTA, and full-bleed dark violet-washed photo hero with display headline, supporting copy and primary/secondary CTAs.","imageRoleId":"hero_office_dark","sourceEvidenceRegionIds":["region-0","region-1","region-2"]},{"id":"region_about_split","purpose":"About/approach editorial split: portrait-orientation practitioner photo in soft lavender blob mask on the left, violet pill badge + H2 ('SEO without the noise.' class) and dense multi-bullet copy on the right (expertise, philosophy, principles).","imageRoleId":"about_portrait_masked","sourceEvidenceRegionIds":["region-3"]},{"id":"region_credibility_strip","purpose":"Light strip with centered Montserrat heading and a horizontal row of ~5 desaturated keyword/sector badges (e.g. 'Ecommerce', 'Hospitality & Travel', 'B2B', 'Professional Services', 'Local Nairobi') at reduced visual weight, since inventing client logos is prohibited.","sourceEvidenceRegionIds":["region-4"]},{"id":"region_services_collection","purpose":"The tall commercial core: violet badge + H2 introducing the six services as an asymmetric card collection — 4-across icon-chip cards (Technical SEO, Local SEO, SEO Content Strategy, Ecommerce SEO), a 2-across wide-card row (SEO Strategy, SEO Audits with longer descriptions), each card white/rounded with icon chip, title, short body and small violet pill action.","imageRoleId":"service_icon_chips","sourceEvidenceRegionIds":["region-5"]},{"id":"region_narrative_split_a","purpose":"Right-aligned image narrative split: medium shot of a practitioner at work with floating descriptive chips (e.g. 'Technical SEO', 'Local SEO — Nairobi'); copy describes the diagnose→prioritise focus without invented metrics.","imageRoleId":"narrative_photo_a","sourceEvidenceRegionIds":["region-6"]},{"id":"region_narrative_split_b","purpose":"Left-aligned image narrative split introducing the four-stage process (01 Diagnose, 02 Prioritise, 03 Execute, 04 Improve) with supporting imagery/illustration montage and floating chips labelled with stage names.","imageRoleId":"narrative_photo_b","sourceEvidenceRegionIds":["region-7"]},{"id":"region_faq","purpose":"Light FAQ band: flat-illustration montage on the left, stacked violet pill accordion rows on the right (first expanded in dark text, rest as saturated violet pills with chevrons) answering SEO service questions using only verified capability facts.","imageRoleId":"faq_illustration","sourceEvidenceRegionIds":["region-8"]},{"id":"region_photo_band","purpose":"Full-bleed darkened office photograph band with overlaid white rounded cards listing verified customer problems (little qualified traffic, competitors ranking above, SEO without strategy, technical issues) and one dark accent card leading into conversion; explicitly adapted from the reference testimonial treatment with zero invented testimonials/ratings.","imageRoleId":"photo_band_office","sourceEvidenceRegionIds":["region-9"]},{"id":"region_newsletter","purpose":"Compact light newsletter band with inline name and email fields plus violet pill submit, framed tightly between the photo band and dark footer.","sourceEvidenceRegionIds":["region-10"]},{"id":"region_contact_footer","purpose":"Dark anchor region: near-black full-width conversion banner ('Ready to make organic search work harder for your business?' + 'Talk to RankForge' pill), then dense dark multi-column footer with contact email hello@rankforgekenya.example, Nairobi/Kenya service-area note, nav links and legal line.","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Business-context documentary-commercial photography, not product display: candid collaborative office scenes darkened for overlaid UI (hero, photo band); one portrait-orientation medium shot of a person at a device inside a soft lavender blob mask (about); medium lightly-posed single-person shots against clean light or lavender backgrounds in narrative splits; flat colorful illustration montages (not photography) beside FAQ and within process imagery. One to two people per frame, gaze toward task or camera, warm-neutral color with moderate contrast, clean restrained backgrounds leaving text-safe negative space. Avoid macro product shots, dramatic cinematic lighting and desaturated fashion-editorial grading.","imageRoles":[{"id":"hero_office_dark","purpose":"Full-bleed candid Kenyan office/collaboration scene (people at laptops) under dark violet wash, providing negative space for headline and CTA on the left.","priority":"CRITICAL"},{"id":"about_portrait_masked","purpose":"Portrait-orientation medium shot of a single SEO practitioner at work, displayed inside a soft lavender circular/blob mask on a light surface.","priority":"CRITICAL"},{"id":"service_icon_chips","purpose":"Small square flat icon/illustration chips (up to 6) representing each verified service, used atop service cards.","priority":"HIGH"},{"id":"narrative_photo_a","purpose":"Medium lightly-posed shot of a person working on search analytics, clean light background, right-aligned in split with floating descriptive chips.","priority":"HIGH"},{"id":"narrative_photo_b","purpose":"Left-aligned photo/illustration montage supporting the four-stage process, clean background, chip-safe negative space.","priority":"HIGH"},{"id":"faq_illustration","purpose":"Flat colorful illustration montage (~3 square figures) beside the FAQ accordion, non-photographic.","priority":"NORMAL"},{"id":"photo_band_office","purpose":"Full-bleed darker-graded office photograph as backdrop for overlaid problem/conversion cards on the left half.","priority":"HIGH"}]},"motionGrammar":["Scroll-triggered reveal transitions on sections and cards (fade + small upward translate, 400–600ms, ease-out), substituting reference parallax per the Adaptation Contract; macro composition stays static.","Floating descriptive chips in narrative splits receive a subtle depth cue (slower/lower-amplitude reveal or gentle hover float) instead of parallax drift.","Violet pill buttons transition color/shadow on hover (~200ms); FAQ accordion rows expand/collapse smoothly (~300ms) with chevron rotation.","Reduced motion: all reveals and floats collapse to instant/opacity-only states; content, focus and state feedback fully preserved.","No structural motion: no horizontal scroll, no section reordering; topology stable under scroll."],"responsiveContract":["375px mobile retains all sections and nav items — everything reflows to single-column stacking, nothing hidden.","Header compresses (~64–72px), centered nav collapses to a hamburger panel; violet pill CTA stays reachable.","Hero: headline scales to ~34px, copy and CTAs stack; background image crops center-left preserving text-safe area; overlay retained.","4-across and 2-across card rows stack to single column, each card retaining icon chip and pill action.","Splits (about, narratives, FAQ) stack image above/below copy; masked portrait scales within its mask.","Photo band keeps overlaid cards, stacked; card backgrounds darken for readability over cropped imagery.","Newsletter fields stack vertically; footer columns collapse to stacked groups with consistent spacing.","No horizontal overflow; no clipped critical content at any breakpoint."],"innerPageVocabulary":["EDITORIAL_SPLIT — image + copy two-column page opener for About/Services; reuse masked-portrait or narrative-photo treatment.","NARROW_NARRATIVE — 720px measure single-column manifesto/principles content with pill badge + H2.","PROCESS_SEQUENCE — numbered 01–04 stage list with icon chips, extending the narrative-split chip language.","CARD_GRID — the 4-across/2-across asymmetric card rows reused for full service detail listings.","QUIET_CTA — compact light band with badge + H2 + violet pill CTA before the dark contact banner.","CONTACT_SPLIT — form (verified field set: Name, Company, Email, Phone, Website, help-topic select, Message) beside illustration montage, feeding the central WAZIBIZ Form Service."],"antiFallbackRules":["Do not replace the asymmetric 4/2 card collection with uniform equal card grids.","Do not drop the lavender blob mask on the about portrait or substitute a plain rectangle.","Do not invent testimonials, star ratings, metrics or client logos — the reference's testimonial cards become verified problem-statement cards.","Do not center all headings; preserve left-aligned badge+H2 pattern except the credibility strip.","Do not add glass, textures, gradient meshes or heavy shadows absent from the reference.","Do not replace pill buttons with square or outlined ghost buttons; the violet pill system with trailing glyphs is systemic.","Do not reduce the services region to a compact 3-card row; preserve the tall multi-row collection.","Do not apply generic fade-up to every element uniformly; follow the motion grammar hierarchy.","Do not copy reference copy, branding, logos, 'Ver Mais' labels or photography in any form."],"accessibilityAdaptations":["All text over photographic backgrounds carries a sufficient dark overlay to meet WCAG AA contrast.","Visible focus rings (violet, offset) on all links, pills, form fields and accordion triggers.","Accordion rows are real buttons with aria-expanded/aria-controls; state is not hover-only.","prefers-reduced-motion removes reveals/floats while preserving all content and feedback.","Form labels explicitly associated with fields; select options use verified service list; visitor email validated and used as Reply-To only.","Mobile body text ≥16px; tap targets ≥44px including pills and nav links."],"declaredLimitations":["Reference heavy parallax is unsupported and replaced by static composition plus reduced reveal/depth cues per the accepted Adaptation Contract (heavy_parallax).","Reference stat/metric chips ('45.80%' style) cannot be reproduced because business facts prohibit invented statistics; chips carry descriptive labels instead.","Reference client-logo strip cannot be reproduced without inventing customers; the strip is adapted to desaturated sector/keyword badges at identical visual weight.","Reference testimonial cards cannot be reproduced without invented reviews; the photo-backed band carries verified customer-problem statements and a conversion card.","Exact reference fonts used as Google-available equivalents (Figtree, Montserrat, Poppins) with matching weights and transforms.","No office address or team facts are verified, so the footer omits a physical address and team roster beyond city/country service-area wording.","Exact reference timing/easing values were unmeasured; motion durations are best-practice approximations within the reduced-motion contract."]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":1,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5499,"completion_tokens_details":{"reasoning_tokens":362},"prompt_tokens":16130,"prompt_tokens_details":{"cached_tokens":16128},"total_tokens":21629}},"createdAt":"2026-09-06T18:16:19.575Z"}},{"runId":"745c56d0-32fc-41d0-9815-867781924b88","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A friendly-authoritative SaaS-agency system for RankForge Kenya: a dark violet photographic hero mass anchors the page, followed by a long light-gray body of badge-titled sections with faint lavender tints, an unusually tall asymmetric services card collection as the commercial core, narrative splits with floating chips, violet pill accordion FAQ, a photo-backed proof band with overlaid cards, and dark newsletter/contact/footer masses framing the bottom. Three-family type stack (Figtree display, Montserrat H2, Poppins body/UI) with capitalize transforms; saturated violet pill buttons with trailing arrow icons are the only strong accent against neutral surfaces. Dark top and bottom, light middle, violet for action only.","signatureTraits":[{"id":"dark-violet-photo-hero-rf","description":"Full-bleed ~1.07-viewport hero (region-2) with a photographic background of people working under a dark purple wash (rgb(48,32,64)-family, luminance <70), carrying the 60px Figtree display headline 'Get found when your customers are already searching.' and a violet pill CTA.","sourceTraitId":"dark-violet-photo-hero"},{"id":"floating-pill-nav-cta-rf","description":"Header bar with centered inline navigation (Poppins 15px/600, capitalize) and a distinct violet pill CTA ('Request an SEO Consultation') at the header's right; compact collapsing mobile menu keeps the pill CTA reachable.","sourceTraitId":"floating-pill-nav-cta"},{"id":"about-split-portrait-rf","description":"Near-full-height (~870px) light editorial split: large portrait-orientation photo displayed ~500px wide inside a soft lavender circular/blob mask on the left, dense multi-bullet copy on the right under a Montserrat 40px H2 with violet pill badge.","sourceTraitId":"about-split-portrait"},{"id":"very-tall-card-collection-rf","description":"Tallest region (~1.86 viewports) holding the six RankForge SEO services as an asymmetric card collection: 4-across icon-chip card row, then 2-across wide cards, then remaining cards; equal white rounded cards with icon tops and per-card violet pill 'Learn more' actions.","sourceTraitId":"very-tall-card-collection"},{"id":"narrative-split-chips-rf","description":"Two sequential narrative splits pairing medium person/environment imagery with copy and small floating cards; chips carry non-quantitative labels (process stage numbers 01–04, focus labels) since RankForge permits no invented statistics.","sourceTraitId":"narrative-split-with-stat-chips"},{"id":"accordion-faq-light-band-rf","description":"~760px light FAQ region with left flat-illustration montage and right-stacked violet pill-shaped accordion rows — first item expanded in dark text, remaining items as saturated violet pills with trailing chevrons.","sourceTraitId":"accordion-faq-light-band"},{"id":"photo-backed-cards-band-rf","description":"Full-bleed office-photography backdrop (luminance mid-darkened) with white rounded cards and one dark accent quote/positioning card overlaid on the left half; for RankForge this band carries positioning/proof-of-approach cards, not invented client testimonials.","sourceTraitId":"photo-backed-testimonials"},{"id":"compact-newsletter-dark-footer-rf","description":"Compact (~341px) newsletter band with inline name/email fields, then a ~720px dark contact region beginning with a near-black full-width conversion banner ('Ready to make organic search work harder…' + 'Talk to RankForge') flowing into a dense multi-column dark footer.","sourceTraitId":"compact-newsletter-dark-contact-footer"}],"fidelityPriorities":["1. Page silhouette and surface sequence: dark hero → light body with lavender tints → photo mass → dark banner/footer framing — the dominant perceived identity.","2. First viewport: full-bleed dark-violet photographic hero with 60px display headline and violet pill CTA.","3. Violet pill button/badge system with trailing icons — every CTA, badge and FAQ row.","4. Region topology: the 12-region order including the unusually tall services collection (~1.86 viewports).","5. Typography relationships: three-family stack with Figtree display, Montserrat 40px H2, Poppins 16px body, capitalize transforms.","6. Photographic grammar: darkened collaborative-office backdrops, masked portrait blob, medium posed-person shots, flat icon/illustration chips.","7. Spacing rhythm and alternating light/dark mass sequencing.","8. Motion: scroll-reveal reveals and floating chips (substituted per Adaptation Contract), accordion behavior."],"tokens":{"color_brand_primary":"#8E2DE2","color_brand_primary_deep":"#4E2FDA","color_hero_wash":"#302040","color_hero_wash_light":"#604070","color_dark_surface":"#101010","color_dark_surface_secondary":"#403030","color_dark_footer_band":"#505050","color_surface_body":"#F9FAFB","color_surface_light":"#F0F0F0","color_surface_lavender_tint":"#F0E0FF","color_text_primary":"#111827","color_text_body":"#374151","color_text_on_strong":"#FFFFFF","color_border_subtle":"#E5E7EB","container_max":"1440px","container_content":"1200px","container_narrow_text":"640px","gutter_mobile":"20px","gutter_intermediate":"32px","gutter_desktop":"48px","space_2xs":"8px","space_xs":"12px","space_sm":"16px","space_md":"24px","space_lg":"40px","space_xl":"64px","space_2xl":"96px","section_tight":"clamp(48px, 5vw, 72px)","section_normal":"clamp(72px, 8vw, 120px)","section_generous":"clamp(96px, 10vw, 160px)","radius_card":"16px","radius_pill":"999px","radius_icon_chip":"12px","font_display":"Figtree, sans-serif","font_heading":"Montserrat, sans-serif","font_body":"Poppins, sans-serif","h1_size":"clamp(36px, 4.2vw, 60px)","h1_line_height":"1.3","h2_size":"clamp(28px, 2.8vw, 40px)","h2_line_height":"1.2","h2_letter_spacing":"0.8px","subhead_bold_size":"clamp(24px, 2.8vw, 40px)","body_size":"16px","body_line_height":"1.4","ui_size":"15px","ui_weight":"600","motion_fast":"200ms","motion_standard":"350ms","motion_focal":"600ms","ease_primary":"cubic-bezier(0.25, 0.1, 0.25, 1)"},"globalGrid":{"containerLogic":"Page max 1440px full-width with full-bleed section surfaces; inner content constrained to ~1200px centered container. Splits use 50/50 or 55/45 asymmetric two-column grids. Card collection uses 4-across, 2-across wide, and 4-across row patterns within the 1200px container. Header uses full-width bar with content aligned to the same 1200px container. Text blocks cap at ~640px measure.","columnRatios":["4-across equal (25% each)","2-across wide (50% each)","50/50 split","55/45 split","40/60 split (illustration/copy in FAQ)"]},"spacingRhythm":"Editorial long-scroll rhythm: generous section paddings (~96–160px desktop, tightening on mobile) between major regions, with intentional exceptions — hero is taller than one viewport, the services collection is deliberately ~1.86 viewports with moderate internal row gaps, and the newsletter band is compact (~341px). Consistent ~40–64px gaps between card rows; ~24–32px card internal padding.","typographyRoles":[{"role":"display_xl / h1","description":"Figtree 700, 60px/78px desktop (clamp to 36px mobile), capitalize, white on dark hero; single largest text mass, 2–3 lines."},{"role":"h2","description":"Montserrat 700, 40px/48px, 0.8px tracking, capitalize, dark text on light surfaces; each section typically preceded by a small violet pill badge label."},{"role":"h3 / sub-block","description":"Figtree 700 bold paragraph-level role, 40px/40px with 0.8px tracking (scale down responsively); used for card titles and split sub-headings, creating compressed hierarchy below H2."},{"role":"body","description":"Poppins 400, 16px/22.4px, rgb(55,65,81); measure 55–75 characters; multi-bullet lists permitted in about split."},{"role":"nav / ui / button","description":"Poppins 15px/600, capitalize, used for header links, pill CTA labels and badges; on violet pills in white."},{"role":"badge","description":"Small violet pill label, Poppins 13–15px/600 capitalize white, placed above section H2s."},{"role":"chip / metadata","description":"Poppins 600 14–16px for floating narrative chips; dark text on white rounded cards or white on violet."}],"colorRoles":[{"role":"brand accent (action violet)","description":"Saturated violet #8E2DE2 (with #4E2FDA deep variant) used ONLY as action/accent: pill CTAs, badges, FAQ pills, icon chips. Low-to-mid page frequency; never floods surfaces."},{"role":"dark anchor surface","description":"Near-black rgb(16,16,16) for the contact banner and newsletter-adjacent mass; dark footer bands rgb(80,80,80)/rgb(64,48,48) family."},{"role":"hero wash","description":"Dark purple photographic overlay rgb(48,32,64)→rgb(96,64,112) gradient wash over hero and proof-band photography, luminance kept low (<70) for text contrast."},{"role":"dominant light surface","description":"Neutral light gray rgb(240,240,240) and body rgb(249,250,251) carry most of the page mass."},{"role":"lavender tint surface","description":"Faint lavender rgb(240,224,255) used occasionally on specific bands and masks, never as page-wide fill."},{"role":"text neutrals","description":"rgb(17,24,39)-family headings, rgb(55,65,81) body, white text on dark/violet surfaces."}],"surfaceLanguage":"Friendly rounded geometry: white cards at ~16px radius with subtle borders/shadows on light gray bands; pill radius (999px) for all buttons, badges and FAQ rows; ~12px radius for icon chips. Soft lavender circular/blob mask on the about portrait. Photography surfaces are darkened by purple overlays rather than gradients-as-decoration. No glassmorphism, no heavy gradients outside the hero/proof photographic washes, no textures. Depth comes from card elevation and surface alternation, not ornament.","headerNavigation":"Full-width header bar (~143px desktop, compressing on mobile): logo left within the 1200px container; centered inline navigation strip (~568px, Poppins 15px/600 capitalize, ~7 links); violet pill CTA ('Request an SEO Consultation') pinned right. Light surface over the dark hero or transparent-over-hero treatment per screenshot; compresses to a compact mobile menu pattern keeping the pill CTA reachable. Static or subtly scrolled-state surface; no mega-menu.","homepageFirstViewport":{"summary":"Header bar plus a full-bleed ~1.07-viewport dark-violet photographic hero (region-2). Background is a candid collaborative-office photograph under a dark purple wash (rgb(48,32,64) dominant, luminance <70). Left-weighted content: 60px Figtree capitalize white headline ('Get found when your customers are already searching.'), 2–3 lines, ~640px block, supporting Poppins body copy (~50–80 words), then a violet pill primary CTA ('Request an SEO Consultation') and a secondary link/pill ('Explore Our Services'). Text-safe negative space preserved in the photography. Slight hint of the next light region visible at the fold is acceptable. Mobile: headline stacks, image crops centered, CTA full-width stack.","regionIds":["region_hero"]},"homepageRegions":[{"id":"region_hero","purpose":"Dark violet full-bleed photographic hero: display headline, supporting organic-visibility copy, primary 'Request an SEO Consultation' pill CTA and secondary 'Explore Our Services' action. Aggregates header/nav strip and hero mass into one compositional unit.","imageRoleId":"img_hero_office","sourceEvidenceRegionIds":["region-0","region-1","region-2"]},{"id":"region_about_split","purpose":"Light near-full-height editorial split introducing RankForge's approach: portrait photo in lavender blob mask left, badge + Montserrat H2 and multi-bullet copy right (technical understanding, search behaviour, content strategy, commercial thinking, disciplined prioritisation).","imageRoleId":"img_about_portrait","sourceEvidenceRegionIds":["region-3"]},{"id":"region_trusted_strip","purpose":"Light strip with centered Montserrat heading and a horizontal row of ~5 desaturated marks. Because RankForge permits no invented client logos, this becomes a 'who we work with' capability strip: sectors served (SMEs, professional services, ecommerce, hospitality, B2B) as desaturated text-mark/sector chips at reduced visual weight.","sourceEvidenceRegionIds":["region-4"]},{"id":"region_services_collection","purpose":"The commercial core: ~1.86-viewport asymmetric collection presenting exactly the six RankForge services (SEO Strategy, Technical SEO, Local SEO, SEO Content Strategy, Ecommerce SEO, SEO Audits) as white rounded cards with icon chips, laid out as 4-across, 2-across wide, then remaining cards, each with a violet pill action.","imageRoleId":"img_service_icons","sourceEvidenceRegionIds":["region-5"]},{"id":"region_process_narrative","purpose":"Two sequential narrative splits presenting the four-stage process (Diagnose, Prioritise, Execute, Improve): alternating image/copy alignment with floating chips carrying stage numbers (01–04) and stage names — no invented statistics.","imageRoleId":"img_narrative_person","sourceEvidenceRegionIds":["region-6","region-7"]},{"id":"region_faq","purpose":"Light FAQ band: left flat-illustration montage, right violet pill accordion rows (first expanded dark-text, rest saturated violet pills with chevrons) answering common SEO service questions within factual constraints.","imageRoleId":"img_faq_illustration","sourceEvidenceRegionIds":["region-8"]},{"id":"region_proof_band","purpose":"Full-bleed darkened office-photography band with overlaid white rounded cards and one dark accent card on the left half. Carries RankForge positioning/proof-of-approach messaging cards (e.g. 'SEO built around commercial growth, not vanity metrics', problem statements) — no invented testimonials or metrics.","imageRoleId":"img_proof_office_bg","sourceEvidenceRegionIds":["region-9"]},{"id":"region_newsletter","purpose":"Compact ~341px band with inline name and email fields and submit pill, submitting via the central WAZIBIZ Form Service (platform sender identity; visitor email as Reply-To).","sourceEvidenceRegionIds":["region-10"]},{"id":"region_contact_footer","purpose":"Dark contact/footer region: near-black full-width conversion banner ('Ready to make organic search work harder for your business?' + 'Talk to RankForge' pill), contact bridge (hello@rankforgekenya.example, Nairobi, Kenya), then dense multi-column dark footer navigation.","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Business-context documentary-commercial photography, not product display. Candid collaborative-office scenes of people working at laptops for hero and proof-band backdrops, darkened under purple washes for overlaid-text readability. One portrait-orientation medium shot of a person at a device for the about split, masked in a soft lavender blob. Medium lightly-posed person shots with clean light/lavender backgrounds for narrative splits. Flat colorful illustration/icon figures (~90px chips, square sources) for service cards and FAQ montage — illustration material, not photography, for those roles. Warm-neutral color, moderate contrast, restrained backgrounds, text-safe negative space where copy overlaps. Avoid: macro product shots, dramatic cinematic lighting, desaturated editorial fashion treatment, sterile studio backgrounds, generic handshake stock poses.","imageRoles":[{"id":"img_hero_office","purpose":"Full-bleed collaborative-office photograph under dark violet wash supporting hero headline and pill CTA; landscape/panoramic, people at laptops, text-safe left negative space. CRITICAL — identity-defining.","priority":"CRITICAL"},{"id":"img_about_portrait","purpose":"Portrait-orientation (2:3) medium shot of one person working at a device, displayed ~500px inside a soft lavender circular/blob mask on a light surface. CRITICAL.","priority":"CRITICAL"},{"id":"img_service_icons","purpose":"Small square flat-color icon/illustration chips (~90px, 1:1) topping the six service cards; illustration material, not photography. HIGH.","priority":"HIGH"},{"id":"img_narrative_person","purpose":"Two medium shots of lightly-posed single people with laptop/tablet against clean light or lavender backgrounds, with floating stage-number chips; alternate left/right alignment. HIGH.","priority":"HIGH"},{"id":"img_faq_illustration","purpose":"Flat colorful illustration montage (~90px figures, mixed) beside the FAQ accordion. NORMAL.","priority":"NORMAL"},{"id":"img_proof_office_bg","purpose":"Full-bleed darkened office photograph as backdrop for overlaid white/dark cards in the proof band. HIGH.","priority":"HIGH"}]},"motionGrammar":["Scroll-triggered reveal transitions on section content and cards (substituting reference parallax per Adaptation Contract): fade + modest 16–24px upward travel, 350–600ms, staggered ~80ms within card rows.","Floating narrative chips receive a subtle slower drift/parallax-lite cue via transform on reveal; disabled under prefers-reduced-motion.","Accordion rows expand/collapse with ~300ms ease; chevron rotates; only one item open at a time.","Violet pill buttons: background deepens toward #4E2FDA with subtle shadow lift on hover, 200ms; focus-visible ring in accessible contrast.","Hero and proof-band backgrounds are static crops (no parallax per Adaptation Contract).","Reduced motion: all reveals render instantly visible; content, focus and state feedback preserved."],"responsiveContract":["375px mobile retains all regions — single-column stacking, no content removal.","Services collection rows (4-across, 2-across) collapse to stacked single-column cards, each retaining icon chip and pill CTA.","Split regions (about, narrative) stack image above copy; portrait scales within its blob mask.","Centered nav strip collapses into compact mobile menu; header height compresses; pill CTA remains reachable.","Full-bleed photo regions (hero, proof band) crop imagery with object-fit cover while retaining overlaid headline/cards.","Trusted strip reduces to a wrapped or scrollable smaller set.","No horizontal overflow at any breakpoint; touch targets ≥44px; mobile type scales per clamp tokens while retaining capitalize transforms and family character."],"innerPageVocabulary":["HERO_BANNER_LIGHT: compact light page-header with badge + Montserrat H2 + short intro (About/Services/Contact).","EDITORIAL_SPLIT_BLOB: 50/50 split with masked portrait/media and multi-bullet copy (About approach).","CARD_COLLECTION_ASYMMETRIC: 4/2/4 card rows for service detail pages (Services).","NARRATIVE_SPLIT_CHIPS: alternating media/copy with floating label chips (process/principle pages).","ACCORDION_PILL_STACK: violet pill FAQ/principle accordion beside illustration montage.","CONTACT_SPLIT: form fields (Name, Company, Email, Phone, Website, help-with select, Message) beside dark info panel with contact bridge.","QUIET_CTA_BAND: compact conversion band reusing the violet pill system before the dark footer."],"antiFallbackRules":["Do not flatten the ~1.86-viewport services collection into a uniform 3-column grid — preserve the 4/2/4 asymmetric rhythm.","Do not replace the dark-violet photographic hero with a plain colored or gradient-only hero.","Do not remove the lavender blob mask from the about portrait in favor of a plain rectangle.","Do not restyle pill CTAs, badges or FAQ rows as squares or sharp rectangles.","Do not flood the page with violet — accent frequency stays low-to-mid on neutral light surfaces.","Do not add glassmorphism, heavy gradients or textures absent from the reference.","Do not center every heading — preserve left-weighted hero and split copy alignment.","Do not drop the black contact banner + dark multi-column footer sequence in favor of a single slim footer.","Do not invent testimonials, statistics or client logos to fill the proof band or trusted strip."],"accessibilityAdaptations":["White-on-violet pills and white-on-dark text meet WCAG AA contrast; body text rgb(55,65,81) on light surfaces.","Hero/proof photographic washes darkened to guarantee ≥4.5:1 overlay text contrast.","Visible focus rings on all pills, nav links, accordion rows and form fields.","Accordion implemented with proper button/aria-expanded semantics; no hover-only essential behavior.","prefers-reduced-motion disables reveals, chip drift and parallax substitutes.","No horizontal overflow; readable mobile type floor ~16px body.","Form fields labeled; select options match the seven permitted help-with values."],"declaredLimitations":["Adaptation Contract: heavy parallax choreography replaced by static composition plus scroll reveals and reduced parallax-lite chip cues (feature token mass:parallax-substitute).","Reference stat/metric chips ('45.80%' style) cannot carry numbers for RankForge (no invented statistics) — chips adapted to stage numbers 01–04 and focus labels while preserving chip geometry and floating placement.","Reference client logos in the trusted strip cannot be reproduced — adapted to desaturated sector/capability text-marks at equivalent visual weight and layout.","Reference testimonial copy/cards adapted to positioning/problem-statement cards over the same photographic backdrop; card geometry preserved.","Exact reference fonts used via Google Fonts (Figtree, Montserrat, Poppins) with sans-serif fallbacks; measured timing values unavailable — motion durations are best-practice estimates.","No invented business facts: testimonials, clients, rankings, team, office address, awards and quantitative claims are all omitted per Business Facts constraints."]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":1,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5775,"completion_tokens_details":{"reasoning_tokens":233},"prompt_tokens":16130,"prompt_tokens_details":{"cached_tokens":16128},"total_tokens":21905}},"createdAt":"2026-09-06T17:55:38.645Z"}},{"runId":"cc062fa6-aded-47b4-8549-8405a7caffaf","artifact":{"schemaVersion":"visual-blueprint/1","stage":"visual-blueprint-generator","value":{"version":"2.0","visualThesis":"A friendly-premium SEO agency system: full-bleed dark-violet photographic hero at the top, then a long light-gray SaaS body where surface shifts sequence the page (dark hero → light about split with masked portrait → light logo strip → very tall asymmetric service-card collection → two narrative splits with floating chips → violet-pill accordion FAQ → photo-backed card band → compact newsletter form → black contact banner and dense dark footer). Violet is a deliberately low-frequency accent confined to pill CTAs, badges, icon chips and accordion pills; all attention is steered to actions. Three-family typography (rounded-geometric display, tracked bold section headings, legible UI body) with capitalize heading voice. Identity is carried by pill-shaped violet buttons with trailing icons, the masked portrait blob, asymmetric card rows of 4/2/4, floating chips, and dark anchor surfaces framing light content.","signatureTraits":[{"id":"dark-violet-photo-hero","description":"Full-bleed ~964px (~1.07 viewport) hero with a photographic background (candid collaborative office scene) under a dark violet wash; 60px display headline and violet pill CTA overlaid with text-safe darkened zones.","sourceTraitId":"dark-violet-photo-hero"},{"id":"floating-pill-nav-cta","description":"Header bar (~143px desktop) with a centered inline navigation strip of 15px/600 capitalize links and a distinct violet pill CTA at the right; collapses to a compact mobile menu keeping the pill CTA reachable.","sourceTraitId":"floating-pill-nav-cta"},{"id":"about-split-portrait","description":"Near-full-height (~870px) light editorial split: large portrait-orientation photo inside a soft lavender circular/blob mask on the left, dense multi-bullet copy on the right.","sourceTraitId":"about-split-portrait"},{"id":"very-tall-card-collection","description":"The tallest region (~1670px, ~1.86 viewports): asymmetric card collection of 6 services — 4-across icon-card row, then 2-across wide cards, then remaining row — equal white rounded cards with small violet pill 'Learn more' actions and square icon chips.","sourceTraitId":"very-tall-card-collection"},{"id":"narrative-split-with-stat-chips","description":"Two sequential narrative splits (~700px and ~870px) pairing medium photo subjects with copy and small floating chips; one image right-aligned, one left-aligned. Chips carry qualitative/stage labels (e.g., process numbers 01–04), never invented metrics.","sourceTraitId":"narrative-split-with-stat-chips"},{"id":"accordion-faq-light-band","description":"~760px light FAQ band: small flat illustration/subject montage on the left, right-stacked violet pill-shaped accordion rows with chevrons; first item expanded in dark text, remaining rows as saturated violet pills.","sourceTraitId":"accordion-faq-light-band"},{"id":"photo-backed-testimonials","description":"Photo-backed card band (~430–480px): full-bleed real workplace photograph darkened, with white rounded cards and one dark accent card overlaying the left half. Content adapted to RankForge: service/positioning cards and stage chips instead of invented client testimonials.","sourceTraitId":"photo-backed-testimonials"},{"id":"violet-pill-button-system","description":"Systemic rounded-pill violet buttons with small trailing arrow/plus glyphs used for every CTA and per-card action; small uppercase pill badges precede section headings; violets rgb(142,45,226) and rgb(78,47,218) family anchor the accent.","sourceTraitId":"violet-pill-button-system"}],"fidelityPriorities":["1. Region/surface sequence — dark hero, light body, lavender tints, photo mass, dark contact/footer; this alternation does most of the page's sequencing work.","2. Hero composition — full-bleed darkened photo with overlaid display headline and violet pill CTA.","3. Violet pill button/badge system — CTA shapes, fills and trailing icons across the entire page.","4. Very tall asymmetric services collection (~1.86 viewports) with 4/2 row rhythm, icon chips and per-card pill CTAs.","5. Typography relationships — three-family stack with 60px display vs 40px H2 vs 16px body contrast and capitalize heading voice.","6. Masked portrait blob in the about split and floating chips in narrative splits.","7. Photo-backed card band and black contact banner + dense dark footer as closing anchors.","8. Responsive identity — single-column stacking that preserves overlays, masks, pill system and all sections without content removal."],"tokens":{"color_violet_primary":"#8E2DE2","color_violet_deep":"#4E2FDA","color_violet_hover":"#6F1FBB","color_hero_wash_dark":"#302040","color_hero_wash_mid":"#604070","color_dark_band":"#101010","color_footer_dark":"#505050","color_body_bg":"#F9FAFB","color_surface_light":"#F0F0F0","color_lavender_tint":"#F0E0FF","color_text_body":"#374151","color_text_on_dark":"#F5F3F7","font_display":"Figtree, 'Poppins', system-ui, sans-serif","font_heading":"Montserrat, 'Poppins', system-ui, sans-serif","font_body":"Poppins, system-ui, sans-serif","size_display_desktop":"60px","size_h2_desktop":"40px","size_subhead_desktop":"40px","size_body":"16px","size_ui":"15px","container_max":"1440px page; content container 1200px","radius_pill":"999px","radius_card":"16px","space_section_desktop":"clamp(64px, 8vw, 112px)","motion_standard":"250ms cubic-bezier(0.4, 0, 0.2, 1)","motion_focal":"600ms cubic-bezier(0.22, 1, 0.36, 1)"},"globalGrid":{"containerLogic":"Full-bleed section surfaces (washes, photo bands, dark banners) span 100vw; inner content constrained to a centered ~1200px container on a 1440px page. Header is full-width with its own inner container. Splits use a two-column grid (image column ~40–45%, copy column ~55–60%). Card collection uses 4-column grid for narrow cards and 2-column grid for wide cards within the same container.","columnRatios":["4-up equal cards","2-up wide cards","45/55 image-copy split","55/45 copy-image split","40/60 FAQ illustration-to-accordion split"]},"spacingRhythm":"Generous, even section padding (~96–112px desktop, halving on mobile) with the services collection internally denser (~48–64px between card rows). Editorial rhythm comes from surface changes and tall regions rather than irregular padding; badges sit ~16px above headings, headings ~24px above copy, cards ~24–32px gaps. Compact exceptions: the newsletter band (~340px) and the trusted-logos strip are deliberately tighter than main content regions.","typographyRoles":[{"role":"display_xl (hero H1)","description":"Figtree 700, 60px/78px desktop (~clamp 34px–60px), capitalize; white on the darkened hero photo; max ~2–3 lines."},{"role":"h2 (section heading)","description":"Montserrat 700, 40px/48px, 0.8px letter-spacing, capitalize; preceded by a small violet pill badge label; used for every major section title."},{"role":"subhead (card/feature title)","description":"Figtree 700, 40px/40px desktop scaling to ~24px in cards, 0.8px tracking; creates compressed hierarchy below H2 inside splits and card titles."},{"role":"body","description":"Poppins 400, 16px/22.4px, neutral gray #374151 on light surfaces, light gray on dark; measure ~60–75 characters."},{"role":"nav / ui / buttons","description":"Poppins 600, 15px, capitalize; used for header links, pill CTA labels, badges and footer utility links."},{"role":"badge label","description":"Small violet-tinted pill, Poppins 600 ~13–14px capitalize; sits directly above each H2."},{"role":"chip label","description":"Compact floating chip text, Poppins 600 ~13–15px; used for process stage numbers/labels in narrative splits."}],"colorRoles":[{"role":"primary accent (violet)","description":"#8E2DE2 as the reference's saturated violet accent: CTA fills, badges, FAQ pills, icon chips. Low-to-mid frequency; never floods surfaces. Exact value stays the brand anchor."},{"role":"deep accent (violet deep)","description":"#4E2FDA for hover states, dark accent cards, gradient depth in the hero wash and selected icon chips."},{"role":"hero wash","description":"Dark violet overlay family (rgb(48,32,64) to rgb(96,64,112)) over the hero photograph, guaranteeing white text contrast."},{"role":"dominant surfaces","description":"Light neutral #F0F0F0-family and body #F9FAFB dominate ~65–70% of the page; occasional faint lavender tints #F0E0FF on specific bands."},{"role":"dark anchors","description":"Near-black #101010 for the contact banner, #505050-family for footer content bands; frame the page top (hero) and bottom (footer)."},{"role":"text","description":"#374151 body on light; near-white on dark/violet surfaces; high-contrast dark text on white cards."},{"role":"borders/dividers","description":"Subtle 1px light borders on cards and inputs; minimal border usage elsewhere — surfaces and pills carry the structure."}],"surfaceLanguage":"Systemic: equal white rounded cards (radius ~16px) with subtle shadows; violet pill fills (radius 999px) with small trailing icons; faint lavender-tinted light bands alternating with plain light gray. Signature: soft lavender circular/blob mask around the about portrait; full-bleed photographic masses under violet or dark overlays; near-black banner strip. Minimal borders; no glassmorphism, no gradients beyond the hero wash, no heavy shadows. Flat illustration chips (~90px squares) appear beside the FAQ and in service icon positions.","headerNavigation":"Desktop header ~143px: logo left, centered inline nav strip (~568px, Poppins 15px/600 capitalize links) with a violet pill CTA ('Request an SEO Consultation') at the right. No transparency/overlap over the hero — the header sits as its own bar above the dark hero. No measured sticky behavior: use a simple static header (or conservative sticky with solid background) rather than inventing scroll-state effects. Mobile: header compresses, nav collapses into a compact menu button, pill CTA remains visible/reachable.","homepageFirstViewport":{"summary":"First viewport = slim header bar (~143px) plus the full-bleed dark-violet photographic hero (~964px, ~1.07 viewport heights): candid collaborative-office photograph under a violet/dark wash, overlaid 60px Figtree capitalize headline 'Get found when your customers are already searching.', short supporting copy on technical SEO/content strategy/focused execution, primary violet pill CTA 'Request an SEO Consultation' and secondary link-style CTA 'Explore Our Services'. Text occupies a left-weighted column with text-safe negative space guaranteed by the darkening overlay; next region (light about split) may just peek on tall viewports.","regionIds":["region_header","region_hero"]},"homepageRegions":[{"id":"region_header","purpose":"Header bar with logo, centered inline navigation and violet pill consultation CTA; collapses to compact mobile menu.","sourceEvidenceRegionIds":["region-0","region-1"]},{"id":"region_hero","purpose":"Full-bleed dark-violet photographic hero with display headline, supporting copy and primary/secondary CTAs about getting found in search.","sourceEvidenceRegionIds":["region-2"],"imageRoleId":"img_hero_office_dark"},{"id":"region_about_split","purpose":"About/positioning split: masked portrait photo (analyst/consultant at work) left, dense multi-bullet copy on RankForge's approach and principles right.","sourceEvidenceRegionIds":["region-3"],"imageRoleId":"img_about_portrait_masked"},{"id":"region_logos_strip","purpose":"Trust strip: centered heading and row of ~5 desaturated placeholder marks (generic wordmarks/sectors served, never fabricated client logos or reference marks); reduces to wrapped set on mobile.","sourceEvidenceRegionIds":["region-4"]},{"id":"region_services_collection","purpose":"Very tall asymmetric services collection for the six SEO services: 4-across icon-card row, 2-across wide cards, remaining cards in a final row; white rounded cards with icon chips and violet pill 'Learn more' actions.","sourceEvidenceRegionIds":["region-5"],"imageRoleId":"img_service_icons"},{"id":"region_narrative_process","purpose":"Two sequential narrative splits presenting RankForge's process (01 Diagnose, 02 Prioritise, 03 Execute, 04 Improve) and approach: medium photo with floating qualitative stage chips, one image right-aligned, one left-aligned.","sourceEvidenceRegionIds":["region-6","region-7"],"imageRoleId":"img_narrative_medium"},{"id":"region_faq","purpose":"Light FAQ band: small flat illustration/subject montage left, violet pill accordion stack right answering common SEO questions (no invented stats); first item expanded.","sourceEvidenceRegionIds":["region-8"],"imageRoleId":"img_faq_montage"},{"id":"region_proof_band","purpose":"Photo-backed card band: full-bleed workplace photograph darkened, white rounded cards plus one dark accent card carrying RankForge's positioning statement and service focus (adapted from testimonial composition; no invented testimonials, ratings or metrics).","sourceEvidenceRegionIds":["region-9"],"imageRoleId":"img_office_backdrop"},{"id":"region_newsletter","purpose":"Compact newsletter/lead band with inline fields wired to the WAZIBIZ Form Service.","sourceEvidenceRegionIds":["region-10"]},{"id":"region_contact_footer","purpose":"Closing conversion anchor: near-black full-width contact banner with closing CTA 'Ready to make organic search work harder for your business?' and 'Talk to RankForge', followed by dense dark multi-column footer with navigation, contact email and service links.","sourceEvidenceRegionIds":["region-11"]}],"imageSystem":{"photographyGrammar":"Environmental business-context photography, not product display: candid to lightly-posed scenes of 1–2 people collaborating at laptops/desk in clean, restrained office environments; warm-neutral to slightly warm grade, moderate contrast, soft natural daylight, no cinematic drama, no desaturated fashion treatment, no macro product shots. Composition leaves text-safe negative space wherever copy or cards overlay imagery; hero and backdrop photos are darkened by violet/dark washes to guarantee contrast. Portrait about shot is a medium shot inside a soft lavender blob/circle mask. Illustration chips are flat, colorful, small-square montage elements for FAQ and service icons. Avoid: reference subjects/branding, stock handshake poses, sterile studio backdrops, hyper-saturation, centered symmetry where asymmetry is specified.","imageRoles":[{"id":"img_hero_office_dark","purpose":"Full-bleed candid collaborative-office scene for the dark-violet hero background; wide landscape, subject off-center left/right leaving text-safe darkened zone; CRITICAL for first-viewport identity.","priority":"CRITICAL"},{"id":"img_about_portrait_masked","purpose":"Portrait-orientation medium shot of a single SEO consultant/analyst at a device, displayed in a soft lavender circular/blob mask on a light surface.","priority":"CRITICAL"},{"id":"img_service_icons","purpose":"Small square flat icon/illustration chips (~56–90px) for the six service cards and FAQ montage; consistent flat colorful style.","priority":"HIGH"},{"id":"img_narrative_medium","purpose":"Two medium shots of single professionals with laptops/tablets against clean light/lavender backgrounds for the process narrative splits, hosting floating stage chips.","priority":"HIGH"},{"id":"img_office_backdrop","purpose":"Full-bleed real-office photograph (wide, density-rich) darkened behind the proof card band with overlaid white/dark cards.","priority":"HIGH"}]},"motionGrammar":["Adaptation Contract: reference heavy scroll-linked parallax is replaced by scroll-triggered reveal transitions and reduced-motion-safe depth cues; macro composition and section rhythm stay static.","Focal motion: floating stage chips in the narrative splits get the most pronounced reveal (slight upward drift + fade, 600ms, staggered) as the substitute parallax focal element.","Supporting motion: sections and cards reveal on scroll with gentle fade/translate-up (~400–600ms, 20–30px travel, small stagger within card rows).","Button/link motion: violet pills shift fill color and shadow on hover/focus (150–250ms); chevrons rotate on accordion expand (~250ms).","Accordion rows expand/collapse with height transition; first item defaults expanded.","No structural motion: no horizontal scroll, no section reordering, no parallax on hero/backdrop photos.","prefers-reduced-motion: remove translations and reveals; show content immediately, preserve color/state feedback and focus visibility."],"responsiveContract":["Breakpoints: desktop 1440 design / ~1200 container, intermediate ~768–1024, mobile 375; viewport meta width=device-width, initial-scale=1.","All 10 canonical regions are retained on mobile — no content removal; sections reflow to single-column stacking.","Card collection: 4-across → 2-across (intermediate) → single-column stacked cards, each keeping its icon chip and pill CTA.","Splits (about, narrative x2, FAQ): image stacks above/below copy; the masked portrait scales down within its blob mask.","Header compresses; centered nav strip collapses to a menu button while the pill CTA stays reachable.","Full-bleed photo regions (hero, proof band) preserve overlay composition by cropping imagery with object-fit: cover and recentering focal points; headline and cards stack.","Logo strip reduces to a wrapped or horizontally scrollable smaller set.","Newsletter inline fields stack vertically on mobile; no horizontal overflow at any breakpoint."],"innerPageVocabulary":["EDITORIAL_SPLIT — image-with-mask one side, copy other side; used for About intro (reuse about-split-portrait language).","NARROW_NARRATIVE — centered narrow text column with pill badge heading; used for About principles narrative.","CARD_COLLECTION_4_2 — the services grid pattern reused for any listable content (About principles, Service detail links).","PROCESS_SEQUENCE — numbered 01–04 stage list with chips, echoing the narrative-split chip language.","QUIET_CTA — light band with badge + H2 + violet pill CTA, pre-footer conversion moment on inner pages.","CONTACT_SPLIT — form column (Name, Company, Email, Phone, Website, help-with select, Message) beside contact context, on light surface; form posts to the WAZIBIZ Form Service.","FAQ_ACCORDION — violet pill accordion reused for service-specific FAQs."],"antiFallbackRules":["Do not shrink the services collection into a single uniform 3-across grid; preserve the 4-across / 2-across asymmetric row rhythm.","Do not replace the dark-violet photographic hero with a plain colored or split-text hero.","Do not flatten the masked portrait blob into a plain rounded rectangle.","Do not convert violet pill buttons into square or outlined buttons; pills with trailing icons are systemic.","Do not center every heading; preserve left-aligned hero and split copy alignment as observed.","Do not add glassmorphism, gradients (beyond the hero wash) or heavy shadows absent from the reference.","Do not remove the black contact banner + dense dark footer in favor of a generic light footer.","Do not invent testimonials, star ratings or numeric metrics to fill the proof band or floating chips; use qualitative/positional content per Business Facts constraints.","Do not drop sections on mobile; stacking, not removal."],"accessibilityAdaptations":["Maintain WCAG AA contrast: white text over hero photo enforced by the dark violet wash; dark text on light surfaces and white cards.","Visible focus rings on all pills, links, accordion headers and form fields (violet focus token on light, light ring on dark).","Accordion implemented as accessible disclosure buttons with aria-expanded; no hover-only essential behavior.","Form fields labeled, required indicators and inline validation; help-with select is a real select element.","prefers-reduced-motion removes reveals/drift while preserving content and state feedback.","Mobile type remains >=16px body; tap targets >=44px for pills and nav.","Desaturated logo-strip marks carry accessible names or are treated as decorative per content truth."],"declaredLimitations":["Adaptation Contract v1: heavy scroll-linked parallax replaced by reveal transitions and reduced-motion-safe depth cues; hero/backdrop parallax drift is intentionally omitted.","Exact reference motion timing/easing unverified (LOW confidence); implemented with conservative 250ms/600ms approximations.","Client constraints prohibit testimonials, metrics, client names, team info and quantitative claims: the proof band reuses the testimonial composition with positioning/service cards, logo strip uses generic desaturated marks, and floating chips carry process stage labels instead of statistics.","No client logo/brand asset supplied; header logo is text-based wordmark treatment until provided.","Exact reference fonts (Figtree/Montserrat/Poppins) loaded via Google Fonts with system fallbacks; metrics may vary ±5% by platform.","Reference analysis extraction confidence is MEDIUM for some typography/UI roles; implementation preserves measured relationships (sizes, ratios) as primary evidence over unverified fine detail."]},"provenance":{"promptId":"visual-blueprint-generator","promptVersion":"v4","promptDomainContractVersion":"v1","model":"glm-5.3-flash","schemaVersion":"visual-blueprint/1","attempt":1,"inputArtifactIds":["builds/65756e7a-a44a-47bc-a7ec-042a8486fc64/v1/reference_analysis.json"],"tokenUsage":{"completion_tokens":5436,"completion_tokens_details":{"reasoning_tokens":177},"prompt_tokens":16130,"prompt_tokens_details":{"cached_tokens":16128},"total_tokens":21566}},"createdAt":"2026-09-06T17:42:58.627Z"}}];
